(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ta"] = {"ui":{"skip":"உள்ளடக்கத்துக்குச் செல்","back":"← AI-gile-க்குத் திரும்பு","lang.button":"மொழி: {name}","lang.dialog":"மொழியைத் தேர்ந்தெடுங்கள்","lang.search":"மொழிகளைத் தேடுங்கள்","lang.none":"பொருந்தும் மொழி இல்லை","lang.notYet":"{name} இன்னும் மொழிபெயர்க்கப்படவில்லை","theme.aria":"தீமை மாற்று: ஒளி, இருண்ட அல்லது கருப்பு","theme.toLight":"ஒளி தீமுக்கு மாற்று","theme.toDark":"இருண்ட தீமுக்கு மாற்று","theme.toBlack":"கருப்பு தீமுக்கு மாற்று (உண்மையான கருப்பு, OLED திரைகளுக்கு இதமானது)","words.underline":"பக்கத்தில் இந்தச் சொற்களுக்கு அடிக்கோடிடு","words.underlineHelp":"புள்ளிக்கோடிட்ட சொல்லின் மேல் சுட்டியை வையுங்கள் அல்லது தட்டுங்கள், அதன் பொருள் தெரியும்.","words.col.todo":"இப்போதைக்குத் தேர்ந்தெடுத்த கார்டுகள்: குழு அடுத்து இவற்றில் தொடங்கும்.","words.col.doing":"ஒரு AI இப்போது இந்த கார்டில் வேலை செய்கிறது.","words.col.review":"ஒரு AI வேலையை முடித்தது; உங்களிடம் வருவதற்கு முன் இன்னொரு AI அதைச் சரிபார்க்கும்.","words.col.verify":"உங்களுக்காகக் காத்திருக்கிறது: முயன்று பார்த்து, வேலை செய்கிறதா என்று சொல்லுங்கள்.","words.col.team":"உங்கள் குறிப்புகள் அல்லது பதில்கள், குழு எடுத்துக்கொள்ளக் காத்திருக்கின்றன.","words.col.done":"முடிந்து ஏற்றுக்கொள்ளப்பட்டது.","index.title":"AI-gile: உங்கள் AI டெவ் டீம், ஒரே போர்டில்","index.description":"AI-gile என்பது AI கோடிங் டீம்களுக்கான கான்பன் போர்டு. நீங்கள் தூங்கும்போது அவர்கள் வேலை செய்கிறார்கள்; நீங்கள் முடிவு செய்ய, சோதிக்க, ஏற்க ஒரு சிறிய குவியல் மட்டும் கிடைக்கும்.","hero.logoAlt":"AI-gile போர்டு ஐகான்","hero.h1.html":"உங்கள் AI டெவ் டீம், ஒரே&nbsp;போர்டில்.","hero.alpha":"🐣 மூடிய ப்ரீ-ஆல்பா","hero.alphaTitle":"ஆரம்ப நிலை, முடியாதது: முயற்சிப்பதற்கு நன்றி!","hero.lede":"நீங்கள் தூங்கும்போது அவர்கள் உருவாக்குகிறார்கள். காலையில் ஒரு சிறிய குவியல்: சில கேள்விகள், சோதிக்க சில விஷயங்கள், ஒன்றிரண்டு ஊதா வைரங்கள். கிளிக் செய்யுங்கள், ஏற்றுக்கொள்ளுங்கள், மீண்டும் காபிக்குத் திரும்புங்கள்.","dl.windows":"Windows ஆப்","dl.browser":"உலாவியில் இயக்குங்கள்","dl.messenger":"📱 உங்கள் போனுக்கான Messenger","dl.soon":"விரைவில் வருகிறது","dl.notify":"🔔 திறக்கும்போது சொல்லுங்கள்","dl.notifySmall":"ஆல்பா அல்லது பீட்டா","hero.secondary":"அஜைல்தான், ஆனால் டீமுக்கு ஸ்டாண்ட்-அப் காபி தேவையே இல்லை. (இருந்தாலும் ஸ்டாண்ட்-அப் நடத்துவார்கள்.)","pitch.h2":"AI-gile, நீங்கள் விரும்பும் எத்தனை சொற்களிலும்","pitch.lede":"ஒரு சொல்லிலிருந்து 144 வரை நீளத்தைத் தேர்ந்தெடுங்கள். ஒவ்வொரு நீளமும் அந்த அளவுக்காக எழுதப்பட்ட தனி விளக்கம். ஸ்லைடரை இழுக்கவும் அல்லது அம்புக்குறி விசைகளைப் பயன்படுத்தவும்.","pitch.rangeLabel":"சொற்களில் நீளம்","pitch.dice":"🎲 இன்னொரு பதிப்பு","pitch.words.one":"{n} சொல்","pitch.words.other":"{n} சொற்கள்","pitch.letters.one":"{n} எழுத்து","pitch.letters.other":"{n} எழுத்துகள்","pitch.chars.one":"{n} குறி","pitch.chars.other":"{n} குறிகள்","count.line.html.one":"இப்போது போர்டில் {n} கார்டு","count.line.html.other":"இப்போது போர்டில் {n} கார்டுகள்","people.humans.html.one":"👥 {n} மனிதர்","people.humans.html.other":"👥 {n} மனிதர்கள்","people.agents.html.one":"🤖 {n} ஏஜென்ட்","people.agents.html.other":"🤖 {n} ஏஜென்ட்கள்","people.working.html.one":"⚡ இப்போது {n} வேலையில்","people.working.html.other":"⚡ இப்போது {n} வேலையில்","pre.title":"AI-gile: ஏதோ ஒன்று உருவாகிறது","pre.description":"இங்கே ஏதோ ஒன்று உருவாகிறது: நீங்கள் கேட்பதை AI அணிகள் உருவாக்கி, அதே நேரத்தில் உங்களுக்குக் கற்றுத்தரும் ஒரு போர்டு. இப்போதைக்கு நண்பர்களுடன் மூடிய ப்ரீ-ஆல்பா.","pre.h1":"இங்கே ஏதோ ஒன்று உருவாகிறது. 🤫","pre.line":"நீங்கள் கேட்பதை AI அணிகள் உருவாக்கி, அதே நேரத்தில் உங்களுக்குக் கற்றுத்தரும் ஒரு போர்டு. இப்போதைக்கு நண்பர்களுடன் மூடிய ப்ரீ-ஆல்பா.","pre.btn":"🔔 திறக்கும்போது சொல்லுங்கள்","pre.peek":"கண்ணாடிக்குப் பின்னால்: உண்மையான போர்டு, நேரலையில். ஒவ்வொரு அட்டையும் ஒரு வண்ணப் பட்டை.","pre.peekFake":"கண்ணாடிக்குப் பின்னால்: வேலை செய்யும் ஒரு போர்டு இப்படித்தான் இருக்கும்.","pre.night":"🌙 இரவுக் காவலர் பொறுப்பில் இருக்கிறார் · 😴 மனிதர் ஓய்வெடுக்கிறார்","features.aria":"இது என்ன செய்கிறது","f.pile.h":"உங்களுக்கு ஒரே குவியல்","f.pile.html":"<b>உங்களுக்கு</b> என்பது எல்லா ப்ராஜெக்ட்களிலும் உங்களுக்காகக் காத்திருக்கும் அனைத்தையும் வைத்திருக்கும்: கேள்விகள், சோதிக்க வேண்டியவை, மனிதர் மட்டுமே செய்யக்கூடிய வேலைகள். உங்கள் வரிசை அடுத்தது என்ன, எவ்வளவு நேரம் ஆகும் என்று சொல்லும்.","f.sleep.h":"நீங்கள் தூங்கும்போது வேலை செய்யும் டீம்கள்","f.sleep.p":"ஒவ்வொரு ப்ராஜெக்டுக்கும் ஒரு லீடும் AI ஏஜென்ட்களின் டீமும் உண்டு. கார்டில் கருத்து எழுதினால் டீம் எழுந்து, வேலையை முடித்து, களைத்த மனிதரும் பின்பற்றக்கூடிய படிகளுடன் திருப்பித் தரும்.","f.tester.h":"AI டெஸ்டர் முதலில் சரிபார்க்கிறார்","f.tester.p":"எதுவும் உங்களிடம் வருவதற்கு முன், டெஸ்டர் ஆப்பின் நகலில் படிகளைப் பின்பற்றி, தான் பார்த்ததை ஸ்கிரீன்ஷாட்டுடன் காட்டுவார். தேர்ச்சி பெற்றவற்றை புரட்டிப் பார்த்து ஒரே கிளிக்கில் ஏற்கலாம்.","f.proof.h":"வாக்குறுதி அல்ல, ஆதாரம்","f.proof.p":"ஒவ்வொரு ஒப்படைப்பும் என்ன மாறியது என்று காட்டும்: கோப்புகள், வேறுபாடு, ஸ்கிரீன்ஷாட்கள். முடிந்ததா என்று பார்க்க ஒவ்வொரு ஆப்பையும் திறக்க வேண்டியதில்லை.","f.chat.h":"உங்கள் லீடுகளுடன் அரட்டை","f.chat.p":"Discord போன்ற பக்கப்பட்டை: ஒரு ப்ராஜெக்டுக்கு ஒரு ஐகான், உங்களுக்குத் தேவையானவற்றுக்கு ஊதா வைரங்கள். லீடுக்கு ஒரு யோசனையை அனுப்புங்கள்; அவர் அதை கார்டுகளாகவும் திட்டமாகவும் மாற்றி, ✅ தொடங்கு பொத்தானுடன் தருவார்.","f.tidy.h":"தன்னைத் தானே ஒழுங்குபடுத்திக் கொள்கிறது","f.tidy.p":"தொடர்புடைய கார்டுகள் ஒன்றாக இணையும், குழப்பமான தலைப்புகள் சரிசெய்யப்படும், டோக்கன் சோதனை கோடை எளிமையாக வைக்கும். மாறிமாறிப் பார்க்க குறைவானவை, யோசிக்க குறைவானவை.","f.private.h":"உங்களுடையது, உங்கள் கணினியில்","f.private.li1":"போர்டு உங்கள் சொந்த கணினியில் இயங்கி உங்களுக்கு மட்டுமே பதிலளிக்கும்.","f.private.li2":"மனிதர்களுக்கிடையேயான தனிப்பட்ட செய்திகள் தொடக்கம் முதல் இறுதி வரை குறியாக்கம் செய்யப்படுகின்றன.","f.private.li3":"கணக்குகள் இல்லை, டிராக்கர்கள் இல்லை, குக்கீகள் இல்லை.","f.lang.h":"உங்கள் மொழியில்","f.lang.p":"டச்சு, வெல்ஷ், ஜப்பானியம் முதல் கடற்கொள்ளையர், யோடா, க்ளிங்கன் வரை 120-க்கும் மேற்பட்ட மொழிகள், கலைச்சொற்களுக்காக ஆங்கிலத்துக்கு விரைவாகத் திரும்பும் வசதியுடன்.","f.service.h":"ஒரு யோசனையிலிருந்து உண்மையான சேவை வரை","f.service.p":"மக்கள் இப்போது பயன்படுத்தும் ஒன்றை AI-உடன் உருவாக்கினீர்களா? அதைச் சேவை எனக் குறியிடுங்கள், அதை நன்றாக நடத்த போர்டு உதவும்: அப்டைம் சோதனைகள், பொது நிலைப் பக்கம், எழுதப்பட்ட ஆய்வுடன் சம்பவங்கள், Go தேவைப்படும் மாற்றங்கள், தினமும் சரிபார்க்கப்படும் பேக்கப்கள். நீங்கள் முன்னேறும்போதே உதவி ஒவ்வொரு படியையும் கற்றுத்தரும்.","msgr.h2":"AI-gile Messenger: உங்கள் குழு உங்கள் பாக்கெட்டில்","msgr.p1":"போர்டைத் திறக்காமலே உங்கள் AI குழுவிடம் பேசுங்கள். உங்கள் ப்ராஜெக்ட் லீட்களுடனும் நண்பர்களுடனும் அரட்டை அடியுங்கள், ஒரு கார்டின் சோதனைப் படிகளைப் பார்த்து பதில் சொல்லுங்கள், எல்லாம் உங்கள் போனிலிருந்தே.","msgr.p2":"இணைக்க, உங்கள் போர்டில் உள்ள QR குறியீட்டை ஸ்கேன் செய்யுங்கள். முதல் முறையா? ஒரு நட்பான டெமோ அரட்டை உங்களுக்கு எல்லாவற்றையும் காட்டும்.","msgr.when":"முதலில் Android, பிறகு போன்களுக்கும் iPhone-க்கும் ஒரு வலைப் பதிப்பு.","msgr.who":"உங்கள் ப்ராஜெக்ட் லீட்","msgr.b1":"டார்க் மோடு சரிசெய்தல் தயார். சோதனைப் படிகள் வேண்டுமா?","msgr.b2":"ஆமாம், தயவுசெய்து!","msgr.b3":"1. Settings-ஐத் திறக்கவும். 2. Dark-ஐத் தேர்ந்தெடுக்கவும். சரியாகத் தெரிகிறதா?","tl.aria":"முதல் உரையாடல் முதல் திட்டம் வரையிலான காலவரிசை","tl.h2":"முதல் அரட்டை முதல் அடுத்து வருவது வரை","tl.lede":"உண்மையான தேதிகளும் நேரங்களும், உங்கள் சொந்த நேர மண்டலத்தில். இன்றுக்குப் பிறகு அது திட்டம் மட்டுமே, தேதிகள் எதுவும் உறுதியளிக்கப்படவில்லை.","tl.today":"இன்று","tl.planned":"திட்டமிடப்பட்டது","tl.doing":"நடப்பில்","tl.cards.one":"{n} கார்டு","tl.cards.other":"{n} கார்டுகள்","join.h2":"இணையுங்கள்","join.lede":"AI-gile-ஐ AuDHD உள்ள, மனநலத்துடன் சில போராட்டங்களைச் சந்தித்த, தாடி வைத்த ஒரு விசித்திரமான மனிதரும் பொறுமையான ஏராளமான ஏஜென்ட்களும் உருவாக்குகிறார்கள். இப்போதைக்கு இது தனிப்பட்டது, நண்பர்களுடன் மூடிய ஆல்பாவில் உள்ளது. திறக்கும்போது முயற்சிக்க விரும்புகிறீர்களா?","join.btn":"ஆர்வத்தைப் பதிவு செய்","join.small":"மின்னஞ்சல் அனுப்புவோம், வேறு எதுவும் இல்லை","footer.tag":"AI-gile. டிராக்கர்கள் இல்லை, குக்கீகள் இல்லை, ஸ்டாண்ட்-அப் காபி இல்லை.","footer.licence":"வணிக உரிமம்","footer.status":"நிலை","footer.privacy":"நாங்கள் வைத்திருப்பவை","footer.thanks":"அழைப்புகளுக்கு ChilledChat-க்கு நன்றி","form.sending":"அனுப்புகிறது…","form.failed":"அது நடக்கவில்லை: பிறகு மீண்டும் முயற்சிக்கவும்.","form.offline":"AI-gile-ஐ அடைய முடியவில்லை: பிறகு மீண்டும் முயற்சிக்கவும்.","form.keep":"உங்களுக்குப் பதில் சொல்ல மட்டுமே இதைப் பயன்படுத்துவோம், பிறகு நீக்கிவிடுவோம். டிராக்கர்கள் இல்லை, குக்கீகள் இல்லை.","form.keepLink":"நாங்கள் வைத்திருப்பவை","interest.title":"AI-gile: ஆல்பா திறக்கும்போது சொல்லுங்கள்","interest.description":"AI-gile-இன் மூடிய ஆல்பா அல்லது பீட்டா திறக்கும்போது தெரிந்துகொள்ள உங்கள் மின்னஞ்சலை விடுங்கள்.","interest.h1":"🔔 திறக்கும்போது சொல்லுங்கள்","interest.lede":"AI-gile மூடிய ப்ரீ-ஆல்பாவில் உள்ளது. உங்கள் மின்னஞ்சலை விடுங்கள்; உங்களுக்கு இடம் இருக்கும்போது ஒரே ஒரு முறை எழுதுவோம்.","interest.email":"உங்கள் மின்னஞ்சல்","interest.which":"எந்தச் சோதனை?","interest.alpha":"மூடிய ஆல்பா: ஆரம்பம், கரடுமுரடு, நிறைய மாற்றங்கள்","interest.beta":"பீட்டா: நிலையானது, பிறகு","interest.both":"எதுவானாலும், எது முதலில் வருகிறதோ","interest.submit":"பட்டியலில் சேருங்கள்","interest.thanks":"நன்றி! நீங்கள் பட்டியலில் இருக்கிறீர்கள்.","licence.title":"AI-gile: வணிக உரிமம்","licence.description":"உங்கள் வணிகத்தில் AI-gile பயன்படுத்துகிறீர்களா? இலவச வணிக உரிமத்துக்கு விண்ணப்பியுங்கள்.","licence.h1":"📜 வணிக உரிமம்","licence.lede":"வேலையில் AI-gile பயன்படுத்துகிறீர்களா? நீங்கள் யார், என்ன செய்கிறீர்கள் என்று சொல்லுங்கள். அது ஏதாவது நன்மை செய்தால், உரிமம் இலவசம்.","licence.company":"நிறுவனம்","licence.website":"இணையதளம்","licence.what":"நீங்கள் என்ன செய்கிறீர்கள்","licence.how":"இது உலகுக்கு எப்படி உதவுகிறது","licence.email":"மின்னஞ்சல்","licence.submit":"விண்ணப்பி","licence.thanks":"நன்றி! மின்னஞ்சலில் பதிலளிப்போம்.","status.title":"AI-gile நிலை","status.h1":"AI-gile நிலை","status.quiet":"அமைதியாக இருக்கிறது","status.intro":"AI-gile இப்போது வேலை செய்கிறதா? இந்தப் பக்கம் 5 நிமிடங்களுக்கு ஒருமுறை இணையதளம், போர்டு பகிர்வு, அழைப்புகள், பதிவிறக்கம் ஆகியவற்றைச் சோதிக்கிறது.","status.up":"வேலை செய்கிறது ({ms} ms-இல் பதில்)","status.slow":"கடைசிச் சோதனைக்குப் பதில் இல்லை, மீண்டும் முயல்கிறது","status.down":"செயலிழந்துள்ளது: கடைசி இரண்டு சோதனைகளுக்கும் பதில் இல்லை","status.svc.web":"இணையதளம்","status.svc.web.offers":"இந்தத் தளம்: AI-gile என்றால் என்ன, மற்றும் ஆர்வப் படிவம்","status.svc.boards":"போர்டு பகிர்வு","status.svc.boards.offers":"பொது போர்டுகள், நண்பர்களுக்கிடையேயான செய்திகள், அழைப்பிதழ்கள்","status.svc.calls":"அழைப்புகள்","status.svc.calls.offers":"AI-gile-இல் குரல், வீடியோ, திரைப் பகிர்வு","status.svc.download":"பதிவிறக்கம்","status.svc.download.offers":"Windows நிறுவியும் அழைப்பிதழ் இணைப்புகளும்","status.checking":"சரிபார்க்கிறது…","status.offline":"நிலைச் சேவையை இப்போது அடைய முடியவில்லை (மீண்டும் முயல்கிறது)","status.updated":"{ago} புதுப்பிக்கப்பட்டது","status.justNow":"இப்போதுதான்","status.min":"{n} நிமிடம் முன்","status.hours":"{n} மணி முன்","status.days":"{n} நாள் முன்","privacy.title":"AI-gile: நாங்கள் வைத்திருப்பவை","privacy.h1":"நாங்கள் வைத்திருப்பவை","privacy.lede":"சுருக்கமாக: நீங்கள் அனுப்புவது மட்டும், அதுவும் நீண்ட காலத்துக்கு அல்ல.","privacy.only":"நீங்கள் அனுப்புவது மட்டும்: உங்கள் மின்னஞ்சல் போல, படிவத்தில் நீங்கள் தட்டச்சு செய்வது. உங்களைப் பற்றி வேறு எதுவும் இல்லை.","privacy.sealed":"எங்கள் சர்வர் படிக்க முடியாதபடி அது முத்திரையிடப்படுகிறது: அது புறப்படும் முன்பே உங்கள் உலாவியில் (பழைய உலாவியில், அது வந்து சேர்ந்த உடனே). எங்கள் சொந்த போர்டு மட்டுமே அதைத் திறக்க முடியும்.","privacy.server":"அது எங்கள் போர்டை அடைந்தவுடனே சர்வரிலிருந்து நீக்கப்படுகிறது. 30 நாட்களுக்குப் பிறகும் அங்கே மீதமிருப்பவை எப்படியும் நீக்கப்படும்.","privacy.board":"உங்களுக்குப் பதில் சொல்லும் வரை மட்டுமே அதை எங்கள் போர்டில் வைத்திருப்போம், பிறகு அங்கிருந்தும் நீக்கிவிடுவோம்.","privacy.none":"டிராக்கர்கள் இல்லை, குக்கீகள் இல்லை, பகுப்பாய்வு இல்லை.","privacy.local":"உங்கள் மொழியும் ஒளி அல்லது இருள் தேர்வும் உங்கள் உலாவியிலேயே இருக்கும். அவை ஒருபோதும் எங்களுக்கு அனுப்பப்படுவதில்லை.","privacy.ask":"இன்னும் சீக்கிரம் நீக்க வேண்டுமா? எங்கள் மின்னஞ்சலுக்குப் பதிலளித்துச் சொல்லுங்கள்.","live.h2":"இது உருவாவதை நேரலையில் பாருங்கள்","live.caption":"ஒவ்வொரு அட்டையும் மறைக்கப்பட்டுள்ளது: நீங்கள் வேலையின் வடிவத்தைப் பார்க்கிறீர்கள், சொற்களை அல்ல.","live.watching.one":"நேரலை: {n} பேர் பார்க்கிறார்கள்","live.watching.other":"நேரலை: {n} பேர் பார்க்கிறார்கள்","live.last.now":"கடைசி அட்டை இப்போதுதான் நகர்த்தப்பட்டது","live.last.min.one":"கடைசி அட்டை {n} நிமிடம் முன்பு நகர்த்தப்பட்டது","live.last.min.other":"கடைசி அட்டை {n} நிமிடங்கள் முன்பு நகர்த்தப்பட்டது","live.last.hour.one":"கடைசி அட்டை {n} மணி நேரம் முன்பு நகர்த்தப்பட்டது","live.last.hour.other":"கடைசி அட்டை {n} மணி நேரம் முன்பு நகர்த்தப்பட்டது","live.last.day.one":"கடைசி அட்டை {n} நாள் முன்பு நகர்த்தப்பட்டது","live.last.day.other":"கடைசி அட்டை {n} நாட்கள் முன்பு நகர்த்தப்பட்டது","live.offline":"நேரலைப் பலகை சற்று ஓய்வெடுக்கிறது. விரைவில் மீண்டும் பாருங்கள்.","live.cols":"பேக்லாக்|செய்ய வேண்டியவை|நடப்பில்|டீம் சரிபார்க்கிறது|நீங்கள் டெஸ்ட் செய்ய|டீமுக்கு|முடிந்தது"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["கான்பன்.","ரோபோக்கள்.","ஒப்படைத்தல்."]},{"n":2,"texts":["ரோபோ கான்பன்.","ஏஜென்ட்கள், ஒழுங்காக.","யோசனைகள், உருவாகின்றன."]},{"n":3,"texts":["ரோபோக்களுக்கான கான்பன்.","யோசனை அம்சமாகிறது.","இலவச ஏஜென்ட் கான்பன்."]},{"n":5,"texts":["ஏஜென்ட்கள் நடத்தும் கான்பன் போர்டு.","நீங்கள் எழுதுங்கள். ஏஜென்ட்கள் உருவாக்குவார்கள்.","இலவசம், உள்ளூர், சோதிக்கப்பட்டது, கொஞ்சம் குறும்பு."]},{"n":8,"texts":["AI ஏஜென்ட்கள் வேலை செய்யும் இலவச கான்பன் போர்டு.","யோசனையை எழுதுங்கள். ஏஜென்ட்கள் உருவாக்கும். நீங்கள் ஏற்கலாம்.","ஒரு மனிதருக்கும் பல பொறுமையான ரோபோக்களுக்குமான அஜைல்."]},{"n":13,"texts":["AI ஏஜென்ட்கள் கார்டுகளை எடுத்து உருவாக்கும், உங்கள் கணினியில் இயங்கும் ஒரு கான்பன் போர்டு.","உங்கள் யோசனையை எழுதுங்கள். அதை ஏஜென்ட்களின் ஒரு டீம் உருவாக்கும். ஒரு டெஸ்டர் அதைச் சரிபார்த்த பிறகு, நீங்களே முடிவு செய்வீர்கள்.","இலவசம், கணக்கு இல்லை, டிராக்கர் இல்லை: ஒரு போர்டு, சில ரோபோக்கள், நீங்களே தலைவர்."]},{"n":21,"texts":["AI-gile என்பது AI கோடிங் ஏஜென்ட்களுடன் சேர்ந்து வேலை செய்ய உதவும் ஒரு கான்பன் போர்டு. கார்டுகளை அவை எடுத்துச் செய்யும்; அவற்றைச் சோதித்து ஏற்பது நீங்கள்.","ஒவ்வொரு ப்ராஜெக்டுக்கும் ஒரு லீடும், AI ஏஜென்ட்கள் அடங்கிய ஒரு டீமும் கிடைக்கும். எந்த ஒரு கார்டிலும் கருத்து எழுதினால், உடனே டீம் வேலையைத் தொடங்கும்.","உங்கள் சொந்த கணினியில் ஓடும், இலவசமான ஒரு தனிப்பட்ட செய்ய வேண்டியவை பட்டியல் இது. வேலை செய்பவர்கள் எல்லாம் ரோபோக்கள். சரி என்று சொல்பவர் மட்டும் நீங்கள்."]},{"n":34,"texts":["உங்கள் யோசனைகளை ஒரு போர்டில் வைக்கிறீர்கள். AI ஏஜென்ட்களின் ஒரு டீம் அவற்றை வேலை செய்யும் அம்சங்களாக மாற்றி, சோதித்து, நீங்கள் முயன்று பார்க்கத் தேவையான படிகளுடன் திருப்பித் தருகிறது. நீங்கள் சொல்லும் வரை எதுவும் முடிந்ததாகக் கணக்கில் வராது.","AI-gile என்பது வீட்டிலேயே செய்த ஒரு கான்பன் போர்டு. இதை ரிச், தான் இப்போது நிர்வகிக்கும் அதே ஏஜென்ட்களின் பெரிய உதவியுடன் உருவாக்கினார். இது இலவசம், உங்கள் கணினியில் ஓடும், நண்பர்களுடன் பகிரப்படுகிறது, விற்கப்படுவதில்லை. இது நண்பர்களுக்காகச் செய்த ஒரு சிறிய முயற்சி.","பேக்லாக் முதல் முடிந்தது வரை நெடுவரிசைகள் கொண்ட சாதாரண கான்பன் போர்டை நினைத்துப் பாருங்கள், கார்டுகளை AI ஏஜென்ட்கள் எடுக்கின்றன என்பது மட்டும் வேறுபாடு. அவை முன்னேற்றம் சொல்லும், சிக்கினால் கேட்கும், உங்கள் பெருவிரல் உயர்வுக்காக எப்போதும் காத்திருக்கும்."]},{"n":55,"texts":["AI-gile என்பது ஒரு கான்பன் போர்டு, இதில் டீமே AI ஏஜென்ட்களால் ஆனது. ஒவ்வொரு ப்ராஜெக்டிலும் வேலையைத் திட்டமிடும் ஒரு லீடும், அதை உருவாக்கும் உதவியாளர்களும் இருக்கிறார்கள். ஒரு அம்சம் தயாரானதும் AI டெஸ்டர் அதைச் சோதித்து ஒரு ஸ்கிரீன்ஷாட் எடுப்பார், பிறகு அது உங்கள் குவியலுக்கு வந்து சேரும். அதை ஏற்கலாம், அல்லது கருத்து எழுதினால் அவர்கள் மீண்டும் செய்வார்கள்.","இது ஒருவர் பல AI கோடிங் அமர்வுகளை ஒரே நேரத்தில் கண்காணிக்க ஆரம்பித்த ஒரு வழி, பிறகு வளர்ந்து ஒரு முழுமையான போர்டு ஆனது. இது உங்கள் கணினியிலேயே ஓடும், கணக்கு எதுவும் தேவையில்லை, டிராக்கர்களும் இல்லை. நண்பர்களுக்கும் ஆர்வமுள்ள எவருக்கும் இலவசம். இது இன்னும் முடியவில்லை, அதனால் சில கரடுமுரடான இடங்களையும் எப்போதாவது ஒரு ஆச்சரியத்தையும் எதிர்பாருங்கள். அதைப் புரிந்துகொண்டு பொறுத்துக்கொள்ளுங்கள், நன்றி.","நேர்மையான பதிப்பு இதோ. யோசனைகள் வைத்திருப்பதும் முடிவுகளைச் சரிபார்ப்பதும் இன்னும் உங்கள் வேலைதான். அதற்கு நடுவில் உள்ள எல்லாவற்றையும் AI-gile செய்கிறது: கார்டுகளை ஒழுங்காக வைக்கிறது, நீங்கள் கருத்து எழுதினால் சரியான ஏஜென்ட்டை எழுப்புகிறது, என்ன மாறியது என்று சரியாகக் காட்டுகிறது, இவை எல்லாவற்றையும் உங்களுக்காக ஒரே ஒரு சிறிய குவியலில் வைக்கிறது. அதனால் ஒரு ஆப்பிலிருந்து இன்னொன்றுக்கு அலைய வேண்டியதில்லை, எதையும் தவற விடவும் மாட்டீர்கள்."]},{"n":89,"texts":["AI-gile என்பது நீங்கள் உங்கள் சொந்த கணினியில் ஓட்டும் ஒரு இலவச கான்பன் போர்டு. மனிதர்களுக்குப் பதிலாக, ஒவ்வொரு ப்ராஜெக்டிலும் AI ஏஜென்ட்களின் ஒரு டீம் இருக்கிறது: உங்கள் யோசனைகளை கார்டுகளாகவும் ஒரு திட்டமாகவும் மாற்றும் ஒரு லீடு, முன்னுரிமை வரிசையில் கார்டுகளை எடுத்துச் செய்யும் உதவியாளர்கள். ஏதாவது உருவானதும், ஒரு AI டெஸ்டர் சோதனைப் படிகளைப் பின்பற்றி, தான் பார்த்ததை உங்களுக்குக் காட்டுவார். பிறகு அது \"உங்களுக்கு\" என்ற ஒரே குவியலில் காத்திருக்கும். நீங்கள் ஏற்கலாம், அல்லது கருத்து எழுதினால் டீம் மீண்டும் ஒரு முறை முயலும். நீங்கள் இல்லாமல் எதுவும் ஒருபோதும் முடிந்தது நெடுவரிசையை அடையாது. இதுவே இதன் முக்கிய விதி.","நீங்கள் எதிர்பார்க்காத சில விஷயங்கள் உண்டு. நீங்கள் தூங்கும்போது இரவுக் காவல், உங்கள் பதில் தேவைப்படாத கார்டுகளைத் தேர்ந்தெடுத்து, செய்ய வேண்டியவை நெடுவரிசையை நிரப்பி வைக்கும். ஏஜென்ட்கள் இன்றும் இந்த வாரமும் எவ்வளவு பயன்படுத்தின என்பதை ஒரு டோக்கன் எண்ணி காட்டும், No Token Mode அவற்றைச் செலவழிப்பதை நிறுத்தச் சொல்லும். நண்பர்களுக்குச் செய்தி அனுப்பலாம், தனிப்பட்ட செய்திகள் தொடக்கம் முதல் இறுதி வரை குறியாக்கம் செய்யப்படுகின்றன. போர்டு டச்சு, ஃபிளெமிஷ், கடற்கொள்ளையர், க்ளிங்கன் உட்பட சுமார் 120 மொழிகளில் பேசும். இவை எதற்கும் ஒரு பைசா கூடச் செலவில்லை, உங்களிடம் எதையும் விற்க யாரும் முயலவும் இல்லை. இவை எல்லாம் நண்பர்களுக்காக, அன்புடன் செய்யப்பட்டவை.","AI-gile ஒரு சிறிய, தனிப்பட்ட திட்டம், ஒரு நிறுவனம் அல்ல. பல AI கோடிங் ப்ராஜெக்ட்களை, ஒவ்வொரு ஆப்பையும் திறந்து பார்க்காமலே கவனிக்க ரிச் விரும்பினார். அதனால் அவரும் ஏஜென்ட்களும் அதற்காக ஒரு போர்டை உருவாக்கி, பிறகு அந்தப் போர்டையே பயன்படுத்தி அதன் மீதிப் பகுதியையும் உருவாக்கினார்கள். இது மூடிய ப்ரீ-ஆல்பாவில் இருக்கிறது, அதாவது ஒரு சில நண்பர்களுக்கு, பெரும்பாலும் வேலை செய்கிறது. விலைப் பக்கம் இல்லை, செய்திமடல் இல்லை, வளர்ச்சித் திட்டமும் இல்லை. பயனுள்ளதாகத் தோன்றினால், இது இன்னும் கொஞ்சம் திறந்ததும் முயன்று பார்க்கக் கேட்கலாம். அதுவரை பொறுமையாகக் காத்திருந்து, எங்களுடன் சேர்ந்து இதைச் சோதிக்க வாருங்கள், உங்கள் கருத்துகள் எங்களுக்கு மிகவும் உதவும்."]},{"n":144,"texts":["AI-gile என்பது ஒரு மனிதருக்கும் பல AI ஏஜென்ட்களுக்குமான ஒரு கான்பன் போர்டு. இது உங்கள் சொந்த கணினியில் ஓடும், முற்றிலும் இலவசம். நீங்கள் ப்ராஜெக்ட்களைச் சேர்க்கிறீர்கள், ஒவ்வொரு ப்ராஜெக்டுக்கும் ஒரு லீடும் ஒரு சிறிய டீமும் கிடைக்கும். Discord போல லீடுடன் அரட்டையடித்து ஒரு யோசனையை விவரிக்கிறீர்கள்; லீடு அதை கார்டுகளாகவும் ஒரு திட்டமாகவும் மாற்றி, நீங்கள் \"தொடங்கு\" என்று அழுத்தும் வரை காத்திருக்கும். மொழி மாதிரிகளுக்காகவே செய்யப்பட்ட ஒரு எளிய கட்டளை வரிக் கருவியைப் பயன்படுத்தி, டீம் கார்டுகளை முன்னுரிமை வரிசையில் ஒன்றன் பின் ஒன்றாகச் செய்யும். எதுவும் உங்களிடம் திரும்பி வருவதற்கு முன், ஒரு AI டெஸ்டர் ஆப்பின் ஒரு நகலில் படிகளைப் பின்பற்றி, ஒரு ஸ்கிரீன்ஷாட்டையும் இணைக்கும். முடிந்த வேலை, மாறிய கோப்புகளுடனும் வேறுபாட்டுடனும் உங்கள் குவியலில் வந்து சேரும். நீங்கள் அதை ஏற்கலாம், அல்லது ஒரு கருத்து எழுதினால் டீம் எழுந்து மீண்டும் முயலும். ஒரு கார்டை \"முடிந்தது\" நெடுவரிசைக்கு நகர்த்த உங்களால் மட்டுமே முடியும். அதனால் எந்த நேரத்திலும், எந்தக் கார்டு எங்கே இருக்கிறது என்பதை நீங்கள் ஒரே பார்வையில் தெரிந்துகொள்ளலாம், எதையும் தேட வேண்டியதில்லை.","AI-gile-உடன் ஒரு நாள், தோராயமாக இப்படி இருக்கும். மாலையில் நீங்கள் சில கருத்துகளை எழுதி வைக்கிறீர்கள்: இந்தப் பொத்தான் தவறான இடத்தில் இருக்கிறது, அந்தப் பட்டியலை வரிசைப்படுத்த வேண்டும், இருண்ட பயன்முறை கிடைக்குமா. பிறகு தூங்கப் போகிறீர்கள். ஏஜென்ட்கள் அந்தக் கருத்துகளைப் படித்து, மாற்றங்களைச் செய்து, அவற்றைச் சோதித்து, உங்களிடம் திருப்பித் தருகின்றன. செய்ய வேண்டியவை காலியாகிவிட்டால், இரவுக் காவல் உங்கள் பதில் தேவைப்படாத கார்டுகளைக் கொண்டு பேக்லாக்கிலிருந்து அதை நிரப்பும். காலையில் ஒரே ஒரு சிறிய குவியல் காத்திருக்கும்: ஓரிரு கேள்விகள், சோதிக்க சில விஷயங்கள், ஒவ்வொன்றும் தூக்கக் கலக்கத்தில் இருப்பவரும் பின்பற்றக்கூடிய படிகளுடனும், அது வேலை செய்வதைக் காட்டும் ஒரு ஸ்கிரீன்ஷாட்டுடனும். நீங்கள் கிளிக் செய்து, நல்லவற்றை ஏற்று, மீதியைத் திருப்பி அனுப்புகிறீர்கள். இவை எல்லாம் எவ்வளவு பயன்படுத்தின என்பதை டோக்கன் எண்ணி காட்டும், சிக்கனமான வாரங்களுக்கு No Token Mode இருக்கிறது. பிறகு நீங்கள் காலை உணவு சாப்பிடுகிறீர்கள், அதில் மட்டும் ஏஜென்ட்களால் இன்னும் உதவ முடியாது. அடுத்த நாள் இரவும் இதே போல் தொடரும், அப்போது உங்களுக்கு வேண்டியது ஒரு கப் தேநீர் மட்டும்தான்.","முதலில், AI-gile என்னவாக இல்லை என்று பார்ப்போம். இது ஒரு ஸ்டார்ட்-அப் அல்ல, விற்பனைக்கு இல்லை, உங்கள் தரவை யாரும் சேகரிக்கவும் இல்லை. இது உங்கள் கணினியில் ஓடும் இலவசப் போர்டு, கணக்குகள் இல்லை, டிராக்கர்கள் இல்லை, குக்கீகளும் இல்லை. இது என்னவாக இருக்கிறது என்றால்: உங்கள் எல்லா AI கோடிங் ப்ராஜெக்ட்களையும் ஒரே நேரத்தில் பார்க்க ஒரு ஒழுங்கான இடம், கார்டுகளை ஏஜென்ட்களின் டீம் செய்ய, முடிவுகளை நீங்கள் எடுக்க. தொடர்புடைய கார்டுகளை ஒன்றாக இணைக்கிறது, குழப்பமான தலைப்புகளைச் சரிசெய்கிறது, கோடு எவ்வளவு எளிமையாக இருக்கிறது என்றும் கவனிக்கிறது. டச்சு, ஃபிளெமிஷ் முதல் கடற்கொள்ளையர், க்ளிங்கன் வரை சுமார் 120 மொழிகளில் பேசுகிறது. நண்பர்கள் ஒருவருக்கொருவர் தனிப்பட்ட முறையில், குறியாக்கத்துடன் செய்தி அனுப்பிக்கொள்ளலாம். இதை ரிச்சும் பொறுமையான ஏராளமான ஏஜென்ட்களும் சேர்ந்து உருவாக்கினார்கள், பெரும்பாலும் இதையே பயன்படுத்தி. இது மூடிய ப்ரீ-ஆல்பாவில் இருக்கிறது, அதனால் சில இடங்களில் கரடுமுரடாக இருக்கும். வேடிக்கையாகத் தோன்றினால், அன்பாகக் கேளுங்கள், சீக்கிரமே உள்ளே வரலாம். எனவே உங்களுக்கு விருப்பமிருந்தால், எந்தத் தயக்கமும் இல்லாமல் எங்களிடம் வந்து கேளுங்கள், நாங்கள் மகிழ்வோம்."]}],"quips":{"1":"ஒரே சொல். துணிச்சல். ஒருவேளை அதிகத் துணிச்சல்.","3":"மூன்று சொற்கள். பெரும்பாலான தயாரிப்புப் பக்கங்களை விட ஏற்கனவே நேர்மையானது.","8":"எட்டுச் சொற்கள். இன்னும் ஸ்டாண்ட்-அப்பை விடச் சிறியது.","21":"நீளங்கள் ஸ்டோரி பாயிண்ட்கள், சொல்லப்போனால். நிச்சயமாக அப்படித்தான்.","55":"ஐம்பத்தைந்து சொற்கள். இதைப் படிக்கும்போது இரண்டு கார்டுகள் முடிந்துவிட்டன.","144":"இதுதான் நீளமானது. 233 என்பது இல்லை. ஏஜென்ட்கள் தூங்கப் போய்விட்டன."}},"timeline":{"first-idea.name":"முதல் யோசனை","first-idea.line":"ஒரு வரி கோடும் இல்லாத காலத்தில் நடந்த முதல் உரையாடல்.","first-board.name":"முதல் போர்டு","first-board.line":"தன் சொந்த உருவாக்கத்தைத் தானே கண்காணிக்கும் போர்டு: கார்டுகள், நெடுவரிசைகள், இழுத்துவிடுதல், ப்ராஜெக்ட்கள்.","team-roles.name":"டீமும் பங்குகளும்","team-roles.line":"ஏஜென்ட் சுயவிவரங்கள், டீம் வார்ப்புருக்கள், இடங்கள், யார் என்ன செய்கிறார்கள்.","install.name":"நிறுவலும் வெளியீடுகளும்","install.line":"நண்பர் நிறுவக்கூடிய ஒரு zip, தானியங்கிப் புதுப்பிப்பு, சேனல்கள், பின்னோக்கித் திரும்புதல்.","usage-saver.name":"பயன்பாட்டுச் சேமிப்பு","usage-saver.line":"இயக்கங்களுக்கான செலவை அளவிடுங்கள், கோடை எளிமையாக வையுங்கள், உங்கள் வரம்பைச் சேமியுங்கள்.","friends.name":"நண்பர்களும் பகிர்வும்","friends.line":"தனிப்பட்ட செய்திகள், குறியாக்கப்பட்ட ரிலே, அழைப்புகள், பங்குகள், பகிரப்பட்ட ப்ராஜெக்ட்கள்.","languages.name":"மொழிகள்","languages.line":"ஒவ்வொரு திரை உரையும் ஒரு மொழிக் கோப்பில், முதலில் டச்சு மற்றும் ஃபிளெமிஷ்.","ai-tester.name":"AI டெஸ்டர்","ai-tester.line":"ஒவ்வொரு ஒப்படைப்பையும் டெஸ்டர் முதலில் சரிபார்த்து, தான் பார்த்ததைக் காட்டுகிறார்.","website.name":"இணையதளம்","website.line":"aigile.lol, முன்னோட்டப் பக்கம் மற்றும் இந்தக் காலவரிசை.","streaming.name":"அரட்டையும் ஸ்ட்ரீமிங்கும்","streaming.line":"Discord, Twitch, OBS, ஸ்ட்ரீமர் பயன்முறை, GIF-களும் எமோஜிகளும்.","no-ai.name":"AI இல்லாத பதிப்பு","no-ai.line":"AI இல்லாமல் கோடிங் செய்பவர்களுக்கான போர்டு, மற்றும் பொது போர்டுகள்.","night-watch.name":"இரவுக் காவல்","night-watch.line":"நீங்கள் தூங்கும்போது காவலரும் Scrum Master-உம் டீம்களை வேலையில் வைத்திருக்கிறார்கள்.","p-more.name":"மற்ற எல்லாம்","p-more.line":"தங்கள் முறைக்காகக் காத்திருக்கும் சிறிய யோசனைகள்.","p-android.name":"போனும் Android-உம்","p-android.line":"போனிலிருந்து உங்கள் போர்டை அணுகுங்கள், பிறகு சொந்த Android ஆப்.","p-release.name":"ஆல்பாவும் அதற்குப் பிறகும்","p-release.line":"மூடிய ஆல்பா, நேரடித் தளம், பிறகு பீட்டா.","p-languages.name":"மேலும் மொழிகள்","p-languages.line":"130 மொழிகள், மொழி கற்பவர்களுக்கு ஒரு மூழ்கல் பயன்முறையும்.","p-engines.name":"மேலும் AI என்ஜின்கள்","p-engines.line":"ஒவ்வொரு ஏஜென்டுக்கும் Claude, Codex, Gemini, Copilot அல்லது Cursor ஐத் தேர்ந்தெடுங்கள்.","p-pro.name":"தொழில்முறை நடைமுறை","p-pro.line":"ஆபத்து லேபிள்கள், மெர்ஜ் வாயில்கள், சம்பவ கார்டுகள், பாதுகாப்புத் தடுப்புகள்.","p-self.name":"உங்களைக் கவனித்துக்கொள்ள","p-self.line":"சோர்வுப் பயன்முறை, சுய-கவனிப்பு நினைவூட்டல்கள், 4:20.","p-servers.name":"சர்வர்களும் வளர்ச்சியும்","p-servers.line":"உலகளாவிய சர்வர் அமைப்புகள், பங்குகள், வளர்ச்சிக்கான திட்டமிடல்.","p-livestream.name":"ஸ்ட்ரீமிங் கூடுதல்கள்","p-livestream.line":"Twitch அரட்டை, தனிப்பயன் எமோஜிகள், பொது நேரலைக் காட்சி."},"words":{"button":"📖 கலைச்சொற்கள்","h":"📖 சொற்கள் விளக்கம்","intro":"AI-gile-இல் நீங்கள் சந்திக்கும் சொற்கள், எளிய மொழியில்: உருவாக்குவது, பாதுகாப்பாக மாற்றுவது, பயன்படுத்துபவர்களுக்காக இயங்க வைப்பது, AI-உடன் ஒரு குழுவாக வேலை செய்வது.","search":"ஒரு சொல்லைத் தேடு…","none":"அந்தச் சொல் எதுவும் பொருந்தவில்லை.","close":"மூடு","count":{"one":"{count} சொல்","other":"{count} சொற்கள்"},"groups":[{"id":"idea","name":"💡 Idea and discovery"},{"id":"plan","name":"🗺️ Planning the work"},{"id":"agile","name":"🔁 Agile ways of working"},{"id":"build","name":"🛠️ உருவாக்குதல்"},{"id":"test","name":"🧪 Testing and quality"},{"id":"change","name":"🔀 பாதுகாப்பாக மாற்றுதல்"},{"id":"run","name":"🛎️ ஒரு சேவையை நடத்துதல்"},{"id":"sec","name":"🔒 Security and privacy"},{"id":"ai","name":"🤖 Working with AI"},{"id":"money","name":"💰 Money and licences"}],"list":[{"id":"discovery","g":"idea","word":"Discovery","text":"The early stage of finding out which problem is worth solving and for whom, before anything gets built.","also":["discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problem statement","text":"One or two sentences saying who has a problem, what it is and why it matters, so everyone aims at the same thing.","also":["problem statements"]},{"id":"user","g":"idea","word":"User","text":"A person who uses what you build. Their needs are what the work is for.","also":["users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Anyone who cares how the work turns out or is affected by it, like the people paying for it, using it or supporting it.","also":["stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"A made-up but realistic person who stands for one kind of user, so the team can ask “would Sam find this easy?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"User research","text":"Talking to and watching real people to learn what they need, rather than guessing.","also":["user interviews"]},{"id":"journey","g":"idea","word":"User journey","text":"The steps a person takes to get something done, from first hearing about it to finishing, also outside your product. Drawing it out shows where they get stuck.","also":["user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Pain point","text":"Something that annoys or slows people down today. Good products take pain points away.","also":["pain points"]},{"id":"assumption","g":"idea","word":"Assumption","text":"Something you believe but haven’t checked yet. Writing assumptions down shows what to test first.","also":["assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothesis","text":"A best guess you plan to check, with what you expect to happen, like “people will sign up if the first month is free”.","also":["hypotheses"]},{"id":"experiment","g":"idea","word":"Experiment","text":"A small planned test to learn whether an idea works, before betting a lot on it.","also":["experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"A quick rough try to see if an idea can work at all. It is usually thrown away once you have the answer.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"An early model of the product, often clickable pictures, to try the idea on people before building it properly.","also":["prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"A simple sketch of a screen showing where things go, without colours or real content.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"A detailed picture of how a screen will look, with real colours and text, but nothing works yet.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"The reasons for doing a project: what it costs, what it brings in or saves, and the risks.","also":["business cases"]},{"id":"feasibility","g":"idea","word":"Feasibility","text":"Whether something can really be built and looked after with the time, money and skills you have."},{"id":"outcome","g":"idea","word":"Outcome","text":"The change you want for people, like fewer missed appointments. It matters more than how much you build.","also":["outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Something the team makes, like a new screen or a report. Making it doesn’t automatically mean it helps anyone.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Success metric","text":"A number that tells you whether the work did what it was for, like more people finishing their order.","also":["success metrics"]},{"id":"kpi","g":"idea","word":"Key performance indicator (KPI)","text":"An important number you watch to see if things are going well, like sign-ups per week.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Objectives and key results (OKRs)","text":"A way of setting goals: the objective says what you want, and a few key results are the numbers that show you got there.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Product","text":"The thing being built and looked after for its users, such as an app, a website or a tool.","also":["products"],"noTip":1},{"id":"vision","g":"plan","word":"Product vision","text":"A short statement of who the product helps and where it is heading in the long run.","also":["vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"The person who decides what gets built and in what order, so the team always works on what matters most. In AI-gile that is you.","also":["PO","product owners"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"The person who looks after a product’s direction: which problems it solves, for whom and why. PM can also mean project manager, so check which.","also":["product managers"]},{"id":"projmgr","g":"plan","word":"Project manager","text":"The person who keeps a project on time and on budget, tracking who does what and by when.","also":["project managers"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"A rough plan of what is coming over the next months, in order. It shows direction, not exact dates, and changes as you learn.","also":["roadmaps"]},{"id":"milestone","g":"plan","word":"Milestone","text":"A point in a project worth marking, like “first version live” or “100 users”.","also":["milestones"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"The smallest version of a product that is still useful to real people, so you can learn from them early.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Requirement","text":"Something the finished product must do or be.","also":["requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Scope","text":"What is included in the work and, just as important, what is not.","also":["in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"When more and more gets added to the work bit by bit, without anyone agreeing on the extra time or cost, so it never quite finishes.","also":["feature creep"]},{"id":"feature","g":"plan","word":"Feature","text":"One thing the product can do for people, like “reset your password”.","also":["features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"A big piece of work, too large for one go, so it is split into smaller cards.","also":["epics"]},{"id":"story","g":"plan","word":"User story","text":"A small piece of work written from the user’s side: “As a shopper, I want to save my basket, so I can finish later.” It starts a conversation about what to build.","also":["user stories"]},{"id":"ac","g":"plan","word":"Acceptance criteria (AC)","text":"The checks one card must pass to count as done, agreed before work starts, like “the basket is still there after I log out and back in”.","also":["acceptance criteria"]},{"id":"task","g":"plan","word":"Task","text":"A single job to be done, often one small step of a bigger story.","also":["tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Another word for a card: one piece of work or one request, tracked from start to finish.","also":["tickets"]},{"id":"priority","g":"plan","word":"Priority","text":"How important or urgent something is compared with everything else, so the most important work goes first.","also":["priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritisation","text":"Putting work in order of importance. A common way is MoSCoW: Must have, Should have, Could have, Won’t have this time.","also":["MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimate","text":"A best guess at how big or how long a piece of work is. It is a guess, not a promise.","also":["estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"A way of guessing the size of work by comparing cards with each other (“about twice as big as that one”) rather than in hours. They aren’t for comparing teams.","also":["story point"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Guessing the size of work as S, M, L or XL. Quick and good enough for early planning.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"A game for estimating: everyone shows a size card at the same time, then the highest and lowest explain why.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dependency","text":"When one piece of work can’t start or finish until another one does.","also":["dependencies"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Anything stopping work from moving forward right now, like a missing answer or a broken tool.","also":["blockers"]},{"id":"deadline","g":"plan","word":"Deadline","text":"The date something must be finished by.","also":["deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable","text":"Something concrete the work produces and hands over, like a working page or a report.","also":["deliverables"]},{"id":"forecast","g":"plan","word":"Forecast","text":"A prediction of what is likely to happen, like when the work will be done, based on what you know so far.","also":["forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metric","text":"Anything you measure and track over time, like page visits or how long a fix takes.","also":["metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"What people tell you about your work, good and bad. Getting it early and often is the heart of Agile.","noTip":1},{"id":"backlog","g":"agile","word":"பேக்லாக்","text":"இன்னும் திட்டமிடாத ஐடியாக்களும் வேலையும். செய்ய வேண்டியவைக்கு நகரும் வரை அங்கே எதுவும் செய்யப்படாது."},{"id":"sprint","g":"agile","word":"ஸ்பிரிண்ட்","text":"முடிக்க வேண்டிய ஒப்புக்கொண்ட கார்டுகளுடன் கூடிய ஒரு குறுகிய வேலைக் காலம் (பெரும்பாலும் ஒன்று அல்லது இரண்டு வாரம்).","also":["ஸ்பிரிண்ட்கள்","sprint","sprints"]},{"id":"standup","g":"agile","word":"ஸ்டாண்ட்-அப்","text":"ஒரு விரைவான சந்திப்பு: ஒவ்வொரு டீம் உறுப்பினரும் என்ன செய்தார், அடுத்து என்ன செய்வார், எது அவரைத் தடுக்கிறது.","also":["ஸ்டாண்டப்","ஸ்டாண்ட்-அப்கள்","standup","stand-up","stand-ups"]},{"id":"kanban","g":"agile","word":"கான்பன்","text":"நெடுவரிசைகள் (செய்ய வேண்டியவை, நடப்பில், முடிந்தது) கொண்ட போர்டு, வேலை நடக்கும்போது கார்டுகள் இடமிருந்து வலமாக நகரும்."},{"id":"wip","g":"agile","word":"WIP வரம்பு","text":"நடப்பில் உள்ள வேலை: ஒரு நெடுவரிசை அதிகபட்சம் வைத்திருக்க வேண்டிய கார்டுகள், அதனால் டீம் மேலும் தொடங்கும் முன் முடிக்கும்.","also":["WIP"]},{"id":"dod","g":"agile","word":"முடிந்தது வரையறை","text":"ஒரு கார்டு உங்களிடம் ஒப்படைக்கப்படும் முன், “முடிந்தது” என்றால் என்ன (சோதிக்கப்பட்டது, விளக்கப்பட்டது போல) என்று சொல்லும் குழுவின் சிறு சரிபார்ப்புப் பட்டியல். அதன் இரட்டை, தயார் வரையறை, ஒரு கார்டு தொடங்கும் அளவுக்குத் தெளிவாக எப்போது இருக்கும் என்று சொல்லும்.","also":["Definition of Done","தயார் வரையறை","Definition of Ready"]},{"id":"retro","g":"agile","word":"ரெட்ரோ","text":"குழு எப்படி வேலை செய்கிறது என்று திரும்பிப் பார்த்து, இன்னும் நன்றாகச் செய்ய ஒரு விஷயத்தில் ஒத்துக்கொள்வது. AI-gile-இல் ஒரு ரெட்ரோ குழுவின் வேலை முறையில் ஒரு மாற்றத்தைப் பரிந்துரைக்கும், நீங்கள் Go அல்லது இன்னும் இல்லை என்று சொல்வீர்கள்.","also":["retro","ரெட்ரோஸ்பெக்டிவ்","retrospective"]},{"id":"swarm","g":"agile","word":"ஸ்வார்ம்","text":"எல்லோரும் களத்தில்: ஒவ்வொரு குழுவும் மற்ற வேலையை விட்டுவிட்டு, ஒரு அவசரத் திட்டம் சரியாகும் வரை உதவும். மற்ற திட்டங்கள் அதுவரை காத்திருக்கும்.","also":["swarm","swarming","திரள்"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"வேலை ஓட்டத்தை வைத்திருப்பவர்: சிக்கிய கார்டுகளைக் கவனிப்பார், குழுக்களைத் தூண்டுவார், என்ன காத்திருக்கிறது என்று உங்களுக்கு நினைவூட்டுவார். AI-gile-இல் Lead Scrum Master இதை எல்லாத் திட்டங்களிலும் செய்வார்.","also":["Lead Scrum Master","ஸ்க்ரம் மாஸ்டர்"]},{"id":"agile","g":"agile","word":"Agile","text":"A way of working in small steps: build a little, show real results often, learn from what people say and change the plan as you go, instead of planning everything up front.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"A short statement written in 2001 by software makers. It puts people, working results, close work with customers and responding to change ahead of heavy plans and paperwork.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"The older way of working: plan everything, then build it all, then test it all, one stage after another. Changes late on are hard and costly.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iteration","text":"One round of building something, checking it and improving it. Agile work is a chain of these, and a sprint is one kind.","also":["iterations"]},{"id":"increment","g":"agile","word":"Increment","text":"A new working piece added to the product in a sprint or round of work, which fits with what was already there.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"A popular Agile way of working: a small team works in short sprints towards a goal, with set roles and a few regular meetings to plan, check and improve."},{"id":"scrumteam","g":"agile","word":"Scrum team","text":"The small group that does the work in Scrum: a product owner, a Scrum Master and the developers.","also":["Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum events","text":"The regular meetings in Scrum: sprint planning, the daily scrum, the sprint review and the retro. Many people call them ceremonies.","also":["ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint planning","text":"The meeting at the start of a sprint where the team agrees why the sprint matters, which cards to take on and how to start.","also":["planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprint goal","text":"One sentence saying what a sprint is for. Small tasks can change along the way, as long as the goal is met.","also":["sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"The cards picked for the current sprint, with the team’s plan for doing them.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"The full ordered list of everything that might be built for the product, most important at the top. It keeps changing as you learn.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Product goal","text":"The bigger result the product is working towards, which helps the team choose what to do next.","also":["product goals"]},{"id":"refinement","g":"agile","word":"Backlog refinement","text":"Regularly going through the backlog to tidy, split, order and add detail to cards, so they are ready to pick up. Also called backlog grooming.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint review","text":"A meeting at the end of a sprint where the team shows what it finished and hears what people think, to decide what comes next.","also":["sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Showing finished work working, live, to the people who asked for it.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"A fixed amount of time for something. When it runs out you stop, even if not everything is done.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity","text":"How much work a team usually finishes in a sprint, used to plan how much to take on next time. It isn’t a score for how hard people work.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Capacity","text":"How much work the team can take on in a period, after holidays and other jobs.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"A chart of the work left in a sprint going down day by day. If the line stays flat, something is stuck.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"A chart of finished work going up over time, next to the total planned, so you can see when you will get there.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban board","text":"The board itself: a column for each stage of the work, with cards moving across.","also":["Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pull system","text":"A way of working where new work only starts when someone has room to take it on, rather than being pushed onto a full plate.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"How smoothly work moves across the board. Good flow means cards keep moving rather than piling up.","also":["flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"How long it takes from someone asking for something to it being finished.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"How long a card takes from when work really starts on it to when it is finished.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"How many cards get finished in a week, or in any set time.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"The one stage where work piles up and slows everything behind it, like the narrow neck of a bottle.","also":["bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"A row across the board that groups cards of one kind, such as urgent work or one team’s cards.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"A way of working that cuts out waste (anything that doesn’t help the customer) and keeps work flowing."},{"id":"waste","g":"agile","word":"Waste","text":"In Lean, anything that takes effort but doesn’t help the customer, like waiting, rework or building things nobody uses.","noTip":1},{"id":"kaizen","g":"agile","word":"Continuous improvement","text":"Getting a little better all the time through small regular changes, then checking they helped. Retros are one way to do it. Also called kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Self-organising team","text":"A team that decides for itself how to do the work, rather than being told step by step.","also":["self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Cross-functional team","text":"A team that has all the skills it needs to finish the work itself, like design, building and testing.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"A short, timeboxed bit of research to answer a question before committing to the real work.","also":["spikes"]},{"id":"rework","g":"agile","word":"Rework","text":"Doing work again because it wasn’t right the first time.","also":["reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Ways of using Agile across many teams in a big organisation. SAFe (the Scaled Agile Framework) is one well known example.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"ரெப்போ","text":"ப்ராஜெக்டின் கோட் கோப்புறையும் அதன் முழு கமிட் வரலாறும், பொதுவாக GitHub-இலும் வைக்கப்படும்.","also":["ரெபாசிட்டரி","repo","repository"]},{"id":"branch","g":"build","word":"பிராஞ்ச்","text":"கோடில் தனி வேலைக் கிளை, அதனால் முதன்மைப் பதிப்பைத் தொடாமல் மாற்றங்கள் செய்யலாம்.","also":["பிராஞ்சுகள்","branch","branches"]},{"id":"commit","g":"build","word":"கமிட்","text":"கோடின் சேமிக்கப்பட்ட ஒரு ஸ்னாப்ஷாட், என்ன மாறியது என்ற சிறு குறிப்புடன். எப்போது வேண்டுமானாலும் ஒன்றுக்குத் திரும்பிப் போகலாம்.","also":["கமிட்கள்","commit","commits"]},{"id":"push","g":"build","word":"புஷ்","text":"சேமித்த ஸ்னாப்ஷாட்களை (கமிட்களை) இந்தக் கணினியிலிருந்து GitHub-க்கு அனுப்புவது, அதனால் அவை காப்புப் பிரதியாகவும் பகிரப்பட்டதாகவும் இருக்கும்."},{"id":"merge","g":"build","word":"மெர்ஜ்","text":"ஒரு பிராஞ்சின் மாற்றங்களை மீண்டும் முதன்மைப் பதிப்புடன் சேர்ப்பது."},{"id":"pr","g":"build","word":"புல் ரிக்வெஸ்ட்","text":"ஒரு பிராஞ்சின் மாற்றங்களைச் சரிபார்த்து முதன்மைப் பதிப்பில் மெர்ஜ் செய்யும்படி கேட்பது.","also":["PR"]},{"id":"refactor","g":"build","word":"ரீஃபாக்டர்","text":"கோடு செய்வதை மாற்றாமல் அதைச் சீர்செய்வது: சிறிய கோப்புகள், தெளிவான பெயர்கள், குறைவான திரும்பத் திரும்ப எழுதிய கோடு."},{"id":"bug","g":"build","word":"பக்","text":"இருக்க வேண்டியபடி வேலை செய்யாத ஒன்று.","also":["பக்குகள்","bug","bugs"]},{"id":"peerreview","g":"build","word":"சக மதிப்பாய்வு","text":"இரண்டாவது ஜோடிக் கண்கள்: ஒவ்வொரு கார்டின் வேலையும் உங்களை அடையும் முன் மற்றொரு AI சரிபார்க்கும், அதனால் குறைவான தவறுகளே தப்பும்.","also":["peer review","பீர் ரிவ்யூ","code review"]},{"id":"code","g":"build","word":"Code","text":"The written instructions that tell a computer what to do. Also called source code.","also":["source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programming language","text":"A language for writing code, such as JavaScript, Python or Java. Different ones suit different jobs.","also":["programming languages"]},{"id":"developer","g":"build","word":"Developer (dev)","text":"Someone who writes and changes code. Also called a programmer or software engineer.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Programs that run on computers and phones, as opposed to the machines themselves (the hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Short for application: a program people use to get something done, on a phone, a computer or in a web browser.","also":["apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"An app that runs in a web browser, so there is nothing to install.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"The part of an app you see and click on: the screens, buttons and words, often in your browser.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"The behind-the-scenes part of an app that keeps the data and does the work when you click something, like checking your password.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Working on both the front end and the back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"User interface (UI)","text":"What a person sees and uses on screen: layout, buttons, menus and text.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"User experience (UX)","text":"How it feels to use something: easy, clear and pleasant, or confusing and slow.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Accessibility (a11y)","text":"Making things usable by everyone, including people who can’t see well, can’t use a mouse or use a screen reader.","also":["a11y"]},{"id":"responsive","g":"build","word":"Responsive design","text":"Making pages fit and work well on any screen size, from a phone to a big monitor."},{"id":"designsys","g":"build","word":"Design system","text":"A shared kit of colours, fonts, buttons and rules, so every screen looks and behaves the same way.","also":["design systems"]},{"id":"architecture","g":"build","word":"Architecture","text":"The overall shape of a system: what the main parts are and how they talk to each other."},{"id":"database","g":"build","word":"Database (DB)","text":"An organised store of information, like a very powerful spreadsheet that the app can read and change.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Database schema","text":"The layout of a database: which tables of information it has and what goes in each.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Short for structured query language: the language used to ask many databases for information or to change it.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Information kept by a computer, like names, orders or settings.","also":["dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"A computer that is always on and answers requests from other computers, like sending a web page when you visit it.","also":["servers"]},{"id":"client","g":"build","word":"Client","text":"The side that asks for something, usually your browser or app, talking to a server. In business it also just means a customer.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Short for application programming interface: a set menu of requests one program can make to another, like asking a weather service for today’s forecast.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"One item on an API’s menu: a web address a program can call to get or send something.","also":["endpoints"]},{"id":"integration","g":"build","word":"Integration","text":"Connecting two systems so they work together, like your shop sending orders to your accounts software.","also":["integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"A message one system sends to another by itself the moment something happens, like “payment received”.","also":["webhooks"]},{"id":"library","g":"build","word":"Library","text":"Ready-made code someone else wrote that you can reuse instead of writing it yourself.","also":["libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"A ready-made structure for building an app that decides much of how the code is laid out, like a house frame you fill in.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"A box of tools, code and examples for building software for one platform or service.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software dependency","text":"A library or tool your code needs to work. Keeping them up to date matters for safety.","also":["software dependencies"]},{"id":"package","g":"build","word":"Package","text":"A bundle of ready-made code you can install and use in a project.","also":["packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager","text":"A tool that fetches and updates the packages your code depends on. npm is a common one.","also":["package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"The most widely used tool for keeping the history of code changes, as commits and branches."},{"id":"github","g":"build","word":"GitHub","text":"A website that keeps Git repos online, so teams can share code, review changes and track work."},{"id":"vcs","g":"build","word":"Version control","text":"Keeping a full history of every change to the files, so you can see who changed what and go back if needed. Git does this.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Making your own full copy of a repo, with its history, on your computer.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Fetching the latest commits from the shared copy (like GitHub) onto your computer. The opposite of push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"The official version of the code that everyone works from, often called main or master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"When two changes touch the same lines in different ways, so the computer can’t join them and a person has to choose.","also":["merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"A view showing exactly what changed between two versions: lines added and lines taken away.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Your own copy of someone else’s repo, which you can change without affecting theirs.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"A short program that does one job by itself, like tidying files or starting the app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Turning the code into something ready to run, or the ready-to-run result itself.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Translating code people wrote into a form the computer can run directly.","also":["compiler"]},{"id":"cli","g":"build","word":"Command line (CLI)","text":"A text window where you type instructions for the computer instead of clicking. Also called the terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Configuration (config)","text":"The settings that control how software behaves, kept apart from the code so they are easy to change.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"A setting handed to a program when it starts, often used for addresses or passwords so they aren’t written into the code.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Hunting down why something isn’t working, and fixing it.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Two people (or a person and an AI) working on the same code together, one typing and one checking.","also":["pairing"]},{"id":"docs","g":"build","word":"Documentation (docs)","text":"Written explanations of how something works or how to use it.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"The first file to read in a repo: what the project is and how to get it running.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacy system","text":"An older system still in use that is hard to change, often because few people still understand it.","also":["legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technical debt","text":"Shortcuts that save time now but make later changes slower, like a loan that builds up interest. Refactoring pays it down.","also":["tech debt"]},{"id":"test","g":"test","word":"டெஸ்ட்","text":"முடிந்த வேலையை ஏற்றுக்கொள்வதற்கு முன், கேட்டபடி செய்கிறதா என்று முயன்று பார்ப்பது.","also":["டெஸ்ட்கள்","test","tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Quality assurance (தர உறுதி) என்பதன் சுருக்கம்: எதுவும் லைவ் போகும் முன் தானாக ஓடும் சோதனைகள். QA சிவப்பாக இருந்தால் ஏதோ தோல்வியடைந்துள்ளது; அது சரியாகும் வரை லைவ் போக முடியாது.","also":["தரச் சோதனை","தரச் சோதனைகள்","தர உறுதி"]},{"id":"testpile","g":"test","word":"சோதனைக் குவியல்","text":"நீங்கள் முயன்று பார்க்கக் காத்திருக்கும் முடிந்த கார்டுகள், ஒன்றன்பின் ஒன்றாக. ஒன்றை ஏற்றுக்கொள்ளுங்கள் அல்லது ஒரு குறிப்புடன் திருப்பி அனுப்புங்கள், அடுத்தது வரும்.","also":["சோதனைக் குவியல்கள்"]},{"id":"autotest","g":"test","word":"Automated test","text":"A check the computer runs by itself every time the code changes, to catch mistakes early.","also":["automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Manual test","text":"A person trying the work by hand to see if it behaves as it should.","also":["manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"A small automatic check of one tiny piece of code on its own.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Integration test","text":"A check that several parts work properly together, not just one at a time.","also":["integration tests"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"A test that acts like a real user from start to finish, such as signing up, buying and paying.","also":["E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"User acceptance testing (UAT)","text":"The people who asked for the work try it themselves and say whether it does what they need. AI-gile’s test pile is its version of this.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Something that used to work but broke after a change. Regression tests check that the old things still work.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"A very quick check that the main things work at all, for example right after a change goes live. If it fails, stop and look.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Exploratory testing","text":"Trying the product freely and poking at it in different ways, to find problems that planned checks would miss.","also":["exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test case","text":"One written scenario to try: the steps, and what should happen.","also":["test cases"]},{"id":"coverage","g":"test","word":"Test coverage","text":"How much of the code is checked by automatic tests. More is usually safer, but high coverage alone doesn’t prove it works well.","also":["code coverage"]},{"id":"testdata","g":"test","word":"Test data","text":"Made-up example information used while testing, so no real person’s private details are exposed.","also":["test fixtures"]},{"id":"edgecase","g":"test","word":"Edge case","text":"An unusual situation at the limits, like an empty form or a name with an apostrophe, where things often break.","also":["edge cases"]},{"id":"happypath","g":"test","word":"Happy path","text":"The normal route where everything goes right. Good testing also tries the unhappy paths."},{"id":"perftest","g":"test","word":"Performance testing","text":"Checking how fast something is and how well it copes under strain.","also":["performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Load testing","text":"Checking how a system copes when lots of people use it at once.","also":["load test","load tests"]},{"id":"sectest","g":"test","word":"Security testing","text":"Looking for weaknesses that could let someone misuse a system or see what they shouldn’t.","also":["security test","security tests"]},{"id":"accesstest","g":"test","word":"Accessibility testing","text":"Checking that people with different abilities can use the product, including with a screen reader or only a keyboard.","also":["accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"An automatic check that spots likely mistakes and messy style in code, like a spelling checker for programs.","also":["linter","lint"]},{"id":"static","g":"test","word":"Static analysis","text":"Checking code for problems by reading it automatically, without running it.","also":["static code analysis"]},{"id":"flaky","g":"test","word":"Flaky test","text":"A test that sometimes passes and sometimes fails for no clear reason, so it can’t be fully trusted.","also":["flaky tests"]},{"id":"repro","g":"test","word":"Reproduce (repro)","text":"Making a bug happen again on purpose by following the same steps, so it can be studied and fixed. Writing those steps down is the most useful part of a bug report.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Severity","text":"How bad a problem’s effect is, from a small annoyance to everything stopping.","also":["severity level"]},{"id":"deploy","g":"change","word":"டெப்ளாய்","text":"புதிய பதிப்பை நேரலைக்குக் கொண்டுவருவது, எடுத்துக்காட்டாக மக்கள் பயன்படுத்தும் சர்வரில்."},{"id":"release","g":"change","word":"வெளியீடு","text":"ஒன்றாக லைவ் போகும், பெயரிடப்பட்ட முடிந்த வேலைகளின் தொகுப்பு; என்ன மாறியது என்ற சிறு குறிப்புகளுடன். 🚀 வெளியீடுகள் முடிந்த கார்டுகளிலிருந்து குறிப்புகளை எழுதும்.","also":["வெளியீடுகள்","ரிலீஸ்","release"]},{"id":"rollback","g":"change","word":"திரும்பப் பெறுதல்","text":"புதிய பதிப்பு சிக்கல் தரும்போது, கடைசியாக வேலை செய்த பதிப்புக்குத் திரும்புவது. AI-gile-இல் இது ஒவ்வொரு மாற்றத்திலும் எழுதப்பட்ட செயல்தவிர் படிகளின் சரிபார்ப்புப் பட்டியலை உருவாக்கும்.","also":["rollback","ரோல்பேக்","திரும்பப் பெறு"]},{"id":"live","g":"change","word":"லைவ்","text":"சோதித்துப் பார்க்கும் நகலைப் போல் இல்லாமல், மக்கள் உண்மையில் பயன்படுத்தும் பதிப்பு. டெவலப்பர்கள் இதை புரொடக்ஷன் என்றும் சொல்வார்கள்.","also":["live","production","புரொடக்ஷன்"],"noTip":1},{"id":"change","g":"change","word":"மாற்றம்","text":"மக்கள் நம்பியிருக்கும் ஒன்றில் திட்டமிட்ட மாற்றம், முதலில் எழுதி வைக்கப்படும்: என்ன, ஏன், இடர், எப்போது, எப்படித் திரும்பப் பெறுவது. 🔀 மாற்றத்தைக் கோரு மூலம் தொடங்குங்கள்.","also":["மாற்றங்கள்","மாற்றக் கோரிக்கை","மாற்றக் கோரிக்கைகள்"],"noTip":1},{"id":"risk","g":"change","word":"இடர்","text":"தவறாகப் போகக்கூடிய ஒன்று; எவ்வளவு சாத்தியம், எவ்வளவு மோசம் என்பதைக் கொண்டு மதிப்பெண் இடப்படும். ⚠️ இடர்கள் அவற்றை ஒரே பட்டியலில் வைக்கும், அதிக மதிப்பெண் முதலில், ஒவ்வொன்றுக்கும் மீண்டும் பார்க்க ஒரு தேதியுடன்.","also":["இடர்கள்","ரிஸ்க்","இடர் பதிவேடு"]},{"id":"chgwin","g":"change","word":"மாற்ற நேர சாளரம்","text":"மாற்றங்கள் லைவ் போகலாம் என்ற நேரங்கள், உதாரணமாக அமைதியான செவ்வாய் மாலை. சாளரத்துக்கு வெளியே, அவசரம் இல்லாவிட்டால் ஒரு மாற்ற கார்டை முடிக்க முடியாது.","also":["மாற்ற நேர சாளரங்கள்","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"ஒரு மாற்றம் லைவ் போவதற்கு சற்று முன் விரைவான வாக்கெடுப்பு: ஒப்புதல் தர வேண்டிய ஒவ்வொருவரும் Go அல்லது No go சொல்வார்கள். அவர்கள் ஒத்துக்கொண்டால் மட்டுமே தொடரும்.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"ஒப்புதல்","text":"வேலை தொடங்கும் முன் ஒரு சரிக்காகக் காத்திருப்பது. நண்பர் கொடுக்கும் கார்டு, அல்லது ஒரு மாற்றம், நீங்கள் ஒப்புதல் தரும் வரை அல்லது மறுக்கும் வரை ✅ ஒப்புதல்கள்-இல் காத்திருக்கும்.","also":["ஒப்புதல்கள்","அனுமதி"]},{"id":"quiettime","g":"change","word":"அமைதி நேரம்","text":"ஸ்ட்ரீம், டெமோ அல்லது இரவு போல, எதுவும் லைவ் போகாத ஒரு காலம். குழுக்கள் வேலை செய்வதும் சோதிப்பதும் தொடரும், ஆனால் லைவ் போவது அது முடியும் வரை காத்திருக்கும். மற்ற இடங்களில் இதை change freeze என்பார்கள்.","also":["அமைதி நேரங்கள்","மாற்ற முடக்கம்","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"A way of working where the people who build software and the people who run it work as one team, with lots of automation, so changes go live often and safely."},{"id":"cicd","g":"change","word":"CI/CD (continuous integration and delivery)","text":"Everyone’s changes are joined into the main version often and checked automatically each time (continuous integration), so the software is always ready to go live at the press of a button (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"One step further than continuous delivery: every change that passes the checks goes live by itself, with no button to press.","also":["continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"The automatic series of steps a change goes through on its way to live, like build, test, then deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Environment","text":"One separate copy of the system for one purpose, such as one to build in, one to test in and the live one.","also":["environments"],"noTip":1},{"id":"devenv","g":"change","word":"Development environment","text":"The copy a developer works in, often on their own computer, where breaking things harms nobody.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Test environment","text":"A separate copy of the system used just for testing, so the real service isn’t touched.","also":["test environments"]},{"id":"staging","g":"change","word":"Staging","text":"A last copy set up just like live, for a final check before a change goes live.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact","text":"The file or bundle a build produces, ready to be stored, checked or put live.","also":["build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"An urgent fix put live quickly, outside the normal plan, because something important is broken.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"A small update that fixes a bug or closes a security hole. Applying security patches quickly matters.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Version number","text":"A label like 2.4.1 that says which release you have. Often the first number changes for big changes and the last for small fixes.","also":["version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Release notes","text":"A short plain list of what changed in a release, for the people who use it, including fixes and known limits. Also called a changelog.","also":["changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"An on and off switch for a feature, so new work can go live hidden and be turned on (or off again) without a new release.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Fixing a bad release by quickly putting out a new, corrected version instead of going back to the old one.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Putting a change live for a small group first, and for everyone only once it looks fine. Named after the canaries miners took underground as an early warning.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Keeping two copies of the live system and switching people over to the new one in one go, so you can switch straight back if it goes wrong.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Putting a new version live without the service ever stopping for its users.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Change enablement","text":"Helping changes succeed: weighing the risk, getting the right approval and picking a good time. Also called change management.","also":["change management"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"A group that looks over important changes and agrees whether and when they may go ahead.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standard change","text":"A low-risk change done the same tried and tested way each time, so it is approved in advance.","also":["standard changes"]},{"id":"normchange","g":"change","word":"Normal change","text":"A change that needs to be checked and approved before it goes ahead.","also":["normal changes"]},{"id":"emergchange","g":"change","word":"Emergency change","text":"A change that must happen right away to fix or prevent serious trouble, with a quicker approval to match.","also":["emergency changes"]},{"id":"automation","g":"change","word":"Automation","text":"Getting the computer to do a repeated job by itself, so it is quicker and done the same way every time.","also":["automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructure","text":"The machines, networks and services that software runs on.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Describing your servers and settings in files kept with the code, so they can be rebuilt exactly the same way every time.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Renting computers, storage and services from a big provider over the internet, instead of owning the machines yourself.","also":["the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Cloud provider","text":"A company that rents out computing over the internet, such as Amazon Web Services (AWS), Microsoft Azure or Google Cloud.","also":["cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Where your app or website lives and runs so people can reach it, usually rented from a company."},{"id":"domain","g":"change","word":"Domain name","text":"The web address people type, like example.com. You rent it by the year, so it must be renewed.","also":["domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Short for domain name system: the internet’s address book, which turns a name like example.com into the address of the right computer.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"A sealed package holding an app and everything it needs, so it runs the same on any computer. Docker is the best known tool.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtual machine (VM)","text":"A pretend computer running inside a real one, so one big machine can act as many.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Running code without looking after any servers yourself: the provider runs it when needed and you pay for what you use."},{"id":"lb","g":"change","word":"Load balancer","text":"Something that spreads visitors across several servers, so no single one gets overwhelmed.","also":["load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"A handy store of recent results kept close by, so the same thing doesn’t have to be fetched or worked out again. Clearing it can fix pages that look out of date.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"A worldwide set of servers holding copies of your pages and pictures near your visitors, so they load quickly.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration","text":"Moving data or systems from an old setup to a new one, or carefully changing how a database is laid out.","also":["migrations","database migration"]},{"id":"service","g":"run","word":"சேவை","text":"நீங்கள் உருவாக்கிய, மக்கள் நம்பியிருக்கும் ஒன்று, இணையதளம் அல்லது ஆப் போல; தொடர்ந்து இயங்க பராமரிக்கப்படும். “இந்தத் திட்டம் ஒரு சேவை” என்பதைத் டிக் செய்து, அது என்ன தருகிறது, யார் பயன்படுத்துகிறார்கள், யார் ஆன்-கால் என்று சொல்லுங்கள்.","also":["சேவைகள்","சர்வீஸ்","service"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"How much of the time a service is working, usually as a percentage. 99.9% still allows about 43 minutes down a month.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"அப்டைம் சோதனை","text":"சில நிமிடங்களுக்கு ஒருமுறை, உங்கள் சேவை இன்னும் பதில் தருகிறதா என்று பார்க்கும் தானியங்கி சோதனை. தொடர்ந்து பலமுறை தோல்வியடைந்தால், AI-gile தானாகவே ஒரு சம்பவ கார்டைத் திறக்கும்.","also":["uptime","அப்டைம்","அப்டைம் சோதனைகள்"]},{"id":"statuspage","g":"run","word":"நிலைப் பக்கம்","text":"ஒரு சேவை இயங்குகிறதா (பச்சை, ஆரஞ்சு அல்லது சிவப்பு) என்பதைச் சமீபத்திய செய்தியுடன் காட்டும் பொதுப் பக்கம்; பயன்படுத்துபவர்கள் கேட்பதற்குப் பதிலாகத் தாங்களே பார்க்கலாம்.","also":["நிலைப் பக்கங்கள்","ஸ்டேட்டஸ் பக்கம்","status page"]},{"id":"desk","g":"run","word":"சேவை டெஸ்க்","text":"உங்கள் சேவையைப் பயன்படுத்துபவர்களிடமிருந்து கேள்விகளும் புகார்களும் வந்து சேரும் இடம். AI-gile ஒவ்வொன்றையும் கோரிக்கை, சம்பவம் அல்லது யோசனை என்று பிரிக்கிறது, ஏற்கெனவே சொல்லப்பட்ட ஒன்று போலத் தெரிந்தால் அதையும் சொல்கிறது.","also":["சேவை டெஸ்க்குகள்","ஹெல்ப் டெஸ்க்","உதவி மையம்","டெஸ்க்"]},{"id":"svcrequest","g":"run","word":"சேவைக் கோரிக்கை","text":"ஏதோ உடைந்திருக்கிறது என்று சொல்வதற்குப் பதில், புதிய கணக்கு அல்லது கொஞ்சம் உதவி போன்ற சாதாரணமான ஒன்றை ஒருவர் கேட்பது. இது தன் முறைக்காகக் காத்திருக்கும்; சம்பவம் முதலில் வரும்.","also":["சேவைக் கோரிக்கைகள்","கோரிக்கை","கோரிக்கைகள்"]},{"id":"incident","g":"run","word":"சம்பவம்","text":"பயன்படுத்துபவர்களுக்கு இப்போதே உடைந்திருக்கும் ஒன்று, உதாரணமாக இணையதளம் வேலை செய்யாதது. ஒரு 🔥 சம்பவ கார்டு வரிசையைத் தாண்டி முன்னே போகும்: மீண்டும் இயங்க வைப்பதே முதல் வேலை.","also":["சம்பவங்கள்","இன்சிடென்ட்","incident"]},{"id":"major","g":"run","word":"பெரிய சம்பவம்","text":"ஒரு பெரிய சம்பவம்: பலர் பாதிக்கப்படுகிறார்கள், அல்லது பணம் அல்லது தரவு ஆபத்தில். ஒரு பொத்தான் எல்லாக் குழுக்களையும் அதில் ஈடுபடுத்தும் (ஸ்வார்ம்), ஆன்-கால் நபரை எழுப்பும், ஒவ்வொரு 30 நிமிடமும் ஒரு நிலைச் செய்தி கேட்கும்.","also":["பெரிய சம்பவங்கள்","major incident"]},{"id":"oncall","g":"run","word":"ஆன்-கால்","text":"ஏதாவது உடைந்தால், இரவிலும் கூட, பதில் தருபவராக இருப்பது. ஒவ்வொரு சேவைக்கும் ஒரு ஆன்-கால் குழு உறுப்பினர் இருப்பார்; அதன் சம்பவங்களுக்கு அவரே முதலில் எழுப்பப்படுவார்.","also":["on call","on-call","ஆன் கால்"]},{"id":"replyby","g":"run","word":"பதில் தரவேண்டிய நேரம்","text":"ஒரு கார்டு முதல் பதிலுக்காக எவ்வளவு நேரம் காத்திருக்கலாம், உதாரணமாக ஒரு சம்பவத்துக்கு ஒரு மணி நேரம். அதன் பிறகு அதற்கு ஒரு சிவப்புக் கடிகாரம் வரும், அதனால் எதுவும் அமைதியாக மறக்கப்படாது. பதில் இலக்கு என்றும் சொல்வார்கள்.","also":["பதில் தரவேண்டிய நேரங்கள்","பதில் இலக்கு"]},{"id":"postmortem","g":"run","word":"போஸ்ட்-மார்ட்டம்","text":"ஒரு சம்பவத்துக்குப் பிறகு சுருக்கமான திரும்பிப் பார்வை: என்ன நடந்தது, எது உதவியது, எதை மாற்ற வேண்டும்; யாரையும் குற்றம் சாட்டாமல். இது இல்லாமல் ஒரு சம்பவத்தை மூட முடியாது.","also":["post-mortem","postmortem","சம்பவத்துக்குப் பிந்தைய ஆய்வு"]},{"id":"problem","g":"run","word":"சிக்கல்","text":"ஒன்று அல்லது பல சம்பவங்களுக்குப் பின்னால் மறைந்திருக்கும் காரணம். ஒரு 🧩 சிக்கல் கார்டு திரும்பத் திரும்ப வரும் சம்பவங்களை ஒன்றாகச் சேர்க்கும், அதனால் காரணம் கண்டுபிடிக்கப்பட்டு நிரந்தரமாகச் சரிசெய்யப்படும்.","also":["சிக்கல்கள்","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"மூல காரணம்","text":"ஏதோ உடைந்ததற்கான உண்மையான காரணம், தவறாகப் போவதாக நீங்கள் பார்த்தது மட்டுமல்ல. மூல காரணத்தைச் சரிசெய்தால் சம்பவம் திரும்ப வருவது நின்றுவிடும்.","also":["மூல காரணங்கள்","root cause"]},{"id":"workaround","g":"run","word":"தற்காலிக வழி","text":"உண்மையான சரிசெய்தல் தயாராகும் வரை விஷயங்களை இயங்க வைக்கும் ஒரு வழி, சிக்கிக்கொண்டால் ஒன்றை மறுதொடக்கம் செய்வது போல. யாரும் மீண்டும் யோசிக்கத் தேவையில்லாமல் இருக்க, இது சிக்கல் கார்டில் எழுதப்படும்.","also":["தற்காலிக வழிகள்","workaround","வொர்க்அரவுண்ட்"]},{"id":"knownerror","g":"run","word":"தெரிந்த பிழை","text":"காரணம் புரிந்த, தற்காலிக வழி உள்ள, ஆனால் இன்னும் சரிசெய்யப்படாத சிக்கல். 🧩 தெரிந்த பிழைகள் அவற்றைப் பட்டியலிடும், அதனால் எல்லோரும் மீண்டும் தோண்டாமல் தற்காலிக வழியைப் பயன்படுத்துவார்கள்.","also":["தெரிந்த பிழைகள்","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"தெரிந்த வகைச் சிக்கலைச் சரிசெய்யப் படிப்படியான வழிமுறைகள், ஒவ்வொரு முறையும் ஒரே மாதிரி, விரைவாகச் செய்ய. ஒரு பெரிய சம்பவத்துக்குப் பிறகு, நீங்கள் சரி சொல்ல குழு ஒன்றைப் பரிந்துரைக்கலாம்.","also":["runbooks","ரன்புக்","செயல்முறைக் கையேடு"]},{"id":"ci","g":"run","word":"கட்டமைப்பு உருப்படி","text":"உங்கள் சேவை சார்ந்திருக்கும் ஒரு விஷயம், உதாரணமாக ஒரு சர்வர், ஒரு டொமைன், ஒரு சான்றிதழ், ஒரு கீ அல்லது ஒரு சப்ளையர். 🗂️ கட்டமைப்பு உருப்படிகள் இவற்றைச் சேவை வாரியாகப் பட்டியலிடும், அதனால் ஒரு சம்பவம் எதைப் பாதிக்கிறது, எதைப் புதுப்பிக்க அல்லது பேக்கப் எடுக்க வேண்டும் என்று பார்க்கலாம்.","also":["கட்டமைப்பு உருப்படிகள்"]},{"id":"expiry","g":"run","word":"காலாவதி தேதி","text":"ஒரு சான்றிதழ் அல்லது டொமைன் எப்போது காலாவதியாகும் போன்ற தேதிகளை AI-gile கவனித்துக்கொள்கிறது. அந்தத் தேதிக்கு 30 நாட்கள் முன்பு அதைப் புதுப்பிக்க ஒரு கார்டு உருவாக்கும், அதனால் எதுவும் திடீரென்று வேலை செய்வதை நிறுத்தாது.","also":["காலாவதி தேதிகள்","காலாவதி","காலாவதி கண்காணிப்பு"]},{"id":"backup","g":"run","word":"பேக்கப்","text":"முன்பு சேமித்த உங்கள் தரவின் நகல்; ஏதாவது தொலைந்தாலோ சேதமடைந்தாலோ நம்பலாம். AI-gile ஒவ்வொரு நாளும் உங்கள் போர்டுகளுக்கு ஒரு பேக்கப் எடுக்கும்.","also":["backup","பேக்கப்கள்","காப்பு நகல்"]},{"id":"restore","g":"run","word":"மீட்டெடுத்தல்","text":"ஒரு பேக்கப்பிலிருந்து தரவைத் திரும்பக் கொண்டுவருவது. மீட்டெடுக்க முடியும் என்று தெரிந்தால்தான் ஒரு பேக்கப் உண்மையில் பயனுள்ளது, அதனால் அவ்வப்போது முயன்று பார்ப்பது நல்லது.","also":["மீட்டெடு","ரீஸ்டோர்","restore"]},{"id":"svcreview","g":"run","word":"சேவை மதிப்பாய்வு","text":"ஒரு சேவையின் ஒரு மாதத்தைத் திரும்பிப் பார்ப்பது: திறக்கப்பட்ட, சரிசெய்யப்பட்ட சம்பவங்கள், மக்களுக்கு எவ்வளவு விரைவில் பதில் கிடைத்தது, அப்டைம், பயன்படுத்திய டோக்கன்கள். மாதாந்திர மதிப்பாய்வு இதை ஒவ்வொரு சேவைக்கும் காட்டும்.","also":["சேவை மதிப்பாய்வுகள்","மாதாந்திர மதிப்பாய்வு","மாதாந்திர மதிப்பாய்வுகள்"]},{"id":"accessreview","g":"run","word":"அணுகல் மதிப்பாய்வு","text":"ஒவ்வொரு 90 நாட்களுக்கும் இன்னும் யார் உள்ளே வர முடியும் என்று சரிபார்ப்பது: பகிர்வு இணைப்புகள், நண்பர்களின் பாத்திரங்கள், சேமித்த ரகசியங்கள். ஒவ்வொன்றையும் வைத்துக்கொள்ளலாம் அல்லது நீக்கலாம், அதனால் பழைய அணுகல் தேவையில்லாமல் தங்காது.","also":["அணுகல் மதிப்பாய்வுகள்"]},{"id":"improvements","g":"run","word":"மேம்பாட்டுப் பட்டியல்","text":"டீம் மேம்படுத்த முடிவு செய்த அனைத்தும் ஒரே இடத்தில்: ரெட்ரோ பரிந்துரைகள், மதிப்பாய்வு நடவடிக்கைகள், சிக்கல் சரிசெய்தல்கள், ஒவ்வொன்றும் அதன் நிலையுடன். 📈 மேம்பாடுகள் என்பதில் காணலாம்.","also":["மேம்பாட்டுப் பட்டியல்கள்","மேம்பாடுகள்"]},{"id":"tokencap","g":"run","word":"டோக்கன் வரம்பு","text":"ஒரு சேவையின் ஏஜென்ட்கள் பயன்படுத்தக்கூடிய டோக்கன்களுக்கான மாதாந்திர வரம்பு. 80%-இல் உங்களுக்கு எச்சரிக்கை வரும்; 100%-இல் அவர்களின் பின்னணி வேலை அடுத்த மாதம் வரை அல்லது நீங்கள் வரம்பை உயர்த்தும் வரை காத்திருக்கும்.","also":["டோக்கன் வரம்புகள்"]},{"id":"svcmgmt","g":"run","word":"Service management","text":"Everything involved in keeping a service useful and working for the people who rely on it, day after day."},{"id":"itil","g":"run","word":"ITIL","text":"A widely used guide to good service management, covering things like incidents, problems and changes. The name once stood for IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT service management (ITSM)","text":"Running technology as a service for people, with clear ways to handle requests, incidents, changes and improvements.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed service","text":"A service someone else runs and looks after for you, under an agreement about how well it must work.","also":["managed services"]},{"id":"svcowner","g":"run","word":"Service owner","text":"The person who answers for a service as a whole: how well it works, what it costs and how it improves.","also":["service owners"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"A written promise to customers about how well a service will work, like “up 99.9% of the time” or “answered within an hour”, often with money back if it is broken.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"The team’s own target for how well a service should work over a period, usually set a bit stricter than the SLA to be safe.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"The actual measurement you check against a target, like the share of visits that loaded fine.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Availability","text":"Whether people can use a service when they need it, often measured as uptime.","also":["high availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Time when a service isn’t working or is switched off, planned or not.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"The small amount of failure your reliability target allows. While some is left you can take risks with changes; once it is used up, you slow down.","also":["error budgets"]},{"id":"outage","g":"run","word":"Outage","text":"A time when a service is down or badly broken for its users.","also":["outages"]},{"id":"degraded","g":"run","word":"Degraded","text":"Working, but badly: slow, or with some parts not working.","also":["degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Watching a service automatically all the time, so problems are spotted, ideally before users notice."},{"id":"observability","g":"run","word":"Observability","text":"How well you can tell what is going on inside a system from the outside, using its logs, numbers and traces.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"A running diary a program keeps of what it is doing, used to work out what went wrong.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"A record of how one request travels through the different parts of a system, step by step, showing where it slowed down.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latency","text":"How long something takes to answer, like the wait between clicking and the page appearing."},{"id":"alert","g":"run","word":"Alert","text":"An automatic message that something needs attention, like the website not answering.","also":["alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alert fatigue","text":"When there are so many alerts that people start ignoring them, including the important ones.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"A screen showing the most important numbers and statuses at a glance.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Urgently calling or waking the on-call person about a problem.","also":["paged"]},{"id":"escalation","g":"run","word":"Escalation","text":"Bringing in someone with more skill or authority when an issue can’t be sorted at the current level, or not fast enough.","also":["escalate","escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Quickly sorting incoming issues by how urgent and important they are, so the worst gets handled first.","also":["triaged"]},{"id":"impact","g":"run","word":"Impact","text":"How much something affects people: how many, and how badly.","noTip":1},{"id":"urgency","g":"run","word":"Urgency","text":"How quickly something needs to be dealt with. Impact and urgency together set the priority.","noTip":1},{"id":"plevels","g":"run","word":"Priority levels (P1, P2…)","text":"Labels for how urgent an issue is. P1 is the most serious and needs action straight away.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticket queue","text":"The list of requests and incidents waiting to be picked up.","also":["ticket queues"]},{"id":"tiers","g":"run","word":"First line and second line","text":"Levels of support: first line takes the call and fixes simple things; second line has deeper skills for harder ones. Also called tier 1 and tier 2.","also":["first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incident commander","text":"The one person who leads the response to an incident, so everyone knows who decides and who does what.","also":["incident commanders"]},{"id":"responsetime","g":"run","word":"Response time","text":"How long it takes before someone first picks up a request or incident.","also":["response times"]},{"id":"resolution","g":"run","word":"Resolution time","text":"How long it takes to fully sort out a request or incident, from report to fixed.","also":["resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"On average, how long it takes to get a service working again after it breaks. MTTR can mean slightly different things, so say what you measure.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"On average, how long a service runs before something breaks.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"The list of all your configuration items and how they connect, so you can see what depends on what.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset","text":"Anything of value you own or pay for to run the service, like a laptop, a software licence or a domain.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Capacity planning","text":"Making sure there will be enough computer power, storage and people for what is coming.","also":["capacity plan"]},{"id":"scaling","g":"run","word":"Scaling","text":"Coping with more users by giving a machine more power (scaling up) or adding more machines (scaling out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Business continuity","text":"Plans for keeping the important things going when something big goes wrong, like losing an office, a key supplier or the computers.","also":["business continuity plan"]},{"id":"dr","g":"run","word":"Disaster recovery (DR)","text":"The plan and tools for getting a service back after something serious, like losing a whole data centre.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"The longest a service may be down after a disaster before it must be working again.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"How much recent data you could afford to lose, measured in time. An RPO of one hour means backups at least every hour.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancy","text":"Having spares ready, like a second server, so one failure doesn’t stop the service."},{"id":"failover","g":"run","word":"Failover","text":"Switching over to a spare system by itself when the usual one fails.","also":["fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"One part that takes everything down with it when it breaks, because there is no spare.","also":["single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Maintenance window","text":"A planned time when a service may be paused or slow for upkeep, announced to users in advance.","also":["maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Handover","text":"Passing work, knowledge and responsibility to another person or team, so nothing gets dropped.","also":["handovers"]},{"id":"kb","g":"run","word":"Knowledge base","text":"A collection of help articles and answers, for users and for the team.","also":["knowledge bases"]},{"id":"csat","g":"run","word":"Customer satisfaction (CSAT)","text":"A score from users saying how happy they were, often asked after a request is closed.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Supplier","text":"An outside company you rely on, like your hosting provider. Also called a vendor or third party.","also":["suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Service retirement","text":"Switching a service off for good, safely: telling its users, dealing with its data and access, and stopping its costs.","also":["retiring a service"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"When a product stops getting updates or support from its maker, so it should be replaced.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cybersecurity","text":"Protecting systems and data from being broken into, stolen or damaged.","also":["cyber security"]},{"id":"authn","g":"sec","word":"Authentication","text":"Checking who someone is, usually with a password or a code. Often shortened to authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Authorisation","text":"Checking what someone is allowed to do once you know who they are. Often shortened to authz.","also":["authz","authorization"]},{"id":"mfa","g":"sec","word":"Multi-factor authentication (MFA)","text":"Logging in with two or more proofs, like a password plus a code on your phone. Also called two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Logging in once to get into many systems, like using your work account everywhere.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Password manager","text":"An app that creates strong passwords and remembers them for you.","also":["password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"A password, key or other private code a program uses to get into something. It must never be shared or written into the code.","also":["secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API key","text":"A secret code that lets a program use another service’s API, and shows who is using (and paying for) it.","also":["API keys"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"A temporary pass that proves a program is allowed in, so it doesn’t need your password each time. Not the same as an AI token.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Encryption","text":"Scrambling information so only someone with the right key can read it.","also":["encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"The secure way web pages travel, shown by the padlock in your browser, so nobody in between can read or change them."},{"id":"cert","g":"sec","word":"SSL/TLS certificate","text":"A digital ID card that lets a website prove who it is and use HTTPS. It expires, so it must be renewed.","also":["TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permissions","text":"The rules for who may see or change what.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege","text":"Giving each person or program only the access they truly need, for only as long as they need it.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Giving access by role, like viewer or editor, rather than person by person.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerability","text":"A weakness that someone could use to break in or cause harm.","also":["vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"A weakness attackers know about before the makers have had any time to fix it.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Harmful software, like viruses, made to damage, spy or steal."},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware that locks up your files and demands money to unlock them. Good backups are the best defence.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Fake messages that try to trick you into giving away passwords or money, or opening something harmful.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Social engineering","text":"Tricking people, rather than computers, into giving access, like a fake call from “IT support”."},{"id":"firewall","g":"sec","word":"Firewall","text":"A guard that decides which network traffic may come in or go out.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Short for virtual private network: a private, scrambled link over the internet, often used to reach work systems safely.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Flooding a service with so much fake traffic that real people can’t use it. DDoS means it comes from many computers at once.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Hiring friendly experts to try to break in, so weaknesses are found before real attackers find them.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Security audit","text":"A careful check of how well something is protected, against a list of good practice.","also":["security audits"]},{"id":"threatmodel","g":"sec","word":"Threat modelling","text":"Thinking through who might attack something, how, and what you would do to stop them.","also":["threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Data breach","text":"When private information gets out to people who shouldn’t have it, or is lost or changed without permission.","also":["data breaches"]},{"id":"pii","g":"sec","word":"Personal data","text":"Any information about a person who can be identified, like a name, email address or location. Also called PII.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"The European law on personal data (the UK has its own version): collect only what you need, keep it safe, and let people see or delete theirs.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Data protection","text":"Looking after personal data properly and within the law.","also":["data protection law"]},{"id":"privacypolicy","g":"sec","word":"Privacy policy","text":"A public page saying what personal data you collect, why, and what you do with it.","also":["privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consent","text":"A person’s clear, free yes to their data being used in a particular way. They can take it back at any time.","also":["opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"A small file a website saves in your browser to remember things, like being logged in. Some need your consent first.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Data minimisation","text":"Collecting and keeping only the personal data you really need for the job.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Data retention","text":"How long data is kept before it is deleted. Keeping it no longer than needed is safer and often the law.","also":["retention period"]},{"id":"anon","g":"sec","word":"Anonymisation","text":"Changing data so nobody can reasonably be identified from it any more.","also":["anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymisation","text":"Swapping names and other details for codes, with a key kept apart to link them back. It is still personal data.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"A contract saying how a supplier may handle personal data on your behalf.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"A careful look, before you start, at how a plan to use personal data could affect people and how to lower the risks.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit log","text":"A record of who did what and when, so actions can be checked later.","also":["audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Compliance","text":"Following the laws, rules and standards that apply to you, and being able to show that you do.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"A well known international standard for managing information security. Companies can be certified against it.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"A US report, checked by outside auditors, showing a company looks after customer data properly.","also":["SOC2"]},{"id":"agent","g":"ai","word":"ஏஜென்ட்","text":"ஒரு பணியில் தானே வேலை செய்யும் AI: கோடைப் படிக்கும், மாற்றங்கள் செய்யும், சோதனைகளை இயக்கும், திரும்பத் தெரிவிக்கும்.","also":["ஏஜென்ட்கள்","agent","agents"]},{"id":"token","g":"ai","word":"டோக்கன்","text":"AI பயன்பாடு கணக்கிடப்படும் அலகு: படித்த அல்லது எழுதிய உரையின் சில எழுத்துகள். குறைவான டோக்கன்கள் என்றால் உங்கள் திட்டத்தில் அதிகம் மீதம்.","also":["டோக்கன்கள்","token","tokens"]},{"id":"hook","g":"ai","word":"ஹூக்","text":"ஒரு குறிப்பிட்ட தருணத்தில் தானே இயங்கும் சிறு கட்டளை, எ.கா. ஒரு AI செஷன் தொடங்கும்போது, அதனால் டீம் உங்கள் கருத்துகளைக் கேட்கிறது.","also":["ஹூக்குகள்","hook","hooks"]},{"id":"ai","g":"ai","word":"Artificial intelligence (AI)","text":"Computer systems that do things we usually think need a person, like writing, answering questions or recognising pictures.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML)","text":"A way of making computers learn patterns from lots of examples, instead of giving them exact rules.","also":["machine learning"]},{"id":"model","g":"ai","word":"Model","text":"The trained “brain” of an AI system, built by learning from huge numbers of examples. Models differ in skill, speed and price.","also":["models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"An AI model trained on vast amounts of text, so it can read and write language.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generative AI","text":"AI that creates new things, like text, pictures or code, rather than only sorting or spotting them.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"A program you talk with in everyday language, by typing or speaking.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"What you give an AI: your question or instructions, plus anything you hand it. Clearer prompts usually get better answers.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"The skill of writing prompts that get reliable, useful results."},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Background instructions an AI gets before the conversation starts, setting its role and rules. They weigh more than what you type.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Context","text":"Everything the AI can see while it works: the instructions, your messages, files it has read and earlier replies.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"How much an AI can keep in mind at once, measured in tokens. Past that, older parts get dropped or summarised.","also":["context windows"]},{"id":"session","g":"ai","word":"Session","text":"One working conversation with an AI, from start to finish. A new session starts with a fresh memory.","also":["sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memory","text":"Notes an AI keeps between sessions, so it remembers your preferences and past decisions.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination","text":"When an AI says something that sounds sure of itself but is made up or wrong. Check important facts.","also":["hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Training","text":"Teaching a model by showing it huge numbers of examples, before anyone uses it.","also":["trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Training data","text":"The examples a model learned from. Its knowledge stops at the date that data was collected.","also":["training set"]},{"id":"cutoff","g":"ai","word":"Knowledge cutoff","text":"The date an AI’s built-in knowledge ends. It won’t know about later things unless it looks them up.","also":["training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Extra training of an existing model on your own examples, to make it better at one particular job.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"An AI model actually being used to answer something, as opposed to being trained.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Tool use","text":"An AI being able to do things, not just talk: run commands, read files or search the web, through tools the app gives it.","also":["tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"A helper AI that a main AI hands a smaller job to, and gets the result back from.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Several AIs working together on one piece of work, each with its own part, like a small team.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomy","text":"How much an AI may do on its own before it has to ask a person.","also":["autonomous"]},{"id":"hitl","g":"ai","word":"Human in the loop","text":"Keeping a person involved to check or approve what the AI does at key points. In AI-gile that is you.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Guardrails","text":"Limits and checks that keep an AI’s actions safe, like needing approval before anything goes live. They lower the risk of mistakes, but don’t rule them out.","also":["guardrail"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Letting an AI look things up in your own documents before it answers, so its answers rest on your facts.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Turning text into a list of numbers that captures its meaning, so a computer can find things that mean similar things.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vector database","text":"A database built to search those lists of numbers (embeddings), to find material with a similar meaning.","also":["vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"A common way to plug tools and data sources into AI apps, so an AI can use them.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperature","text":"A setting for how adventurous an AI’s answers are. Low gives steadier, more predictable answers; high gives more varied ones. Neither makes it always right.","also":["model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Able to work with more than one kind of information, such as text, pictures and sound.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Evaluation (eval)","text":"A planned test of how well an AI does on chosen examples, so you can compare models or prompts.","also":["eval","evals"]},{"id":"bias","g":"ai","word":"Bias","text":"When an AI (or a person) leans unfairly one way, often because of what it learned from.","also":["biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Responsible AI","text":"Using AI fairly, safely and honestly, with people still answerable for the results.","also":["ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"A trick where hidden instructions in a web page or file try to make an AI do something its user didn’t ask for.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"A cap on how many requests you may send to a service in a set time. Go over it and you have to wait.","also":["rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Usage limit","text":"How much AI work your plan allows in a period, after which it pauses or costs more.","also":["usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Building software mostly by describing what you want to an AI and letting it write the code.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budget","text":"The amount of money set aside for something.","also":["budgets"],"noTip":1},{"id":"costest","g":"money","word":"Cost estimate","text":"A best guess at what something will cost before you start.","also":["cost estimates"]},{"id":"roi","g":"money","word":"Return on investment (ROI)","text":"What you get back compared with what you put in. If it is positive, it was worth it.","also":["ROI"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Everything something really costs over its whole life, not just the price to buy it: running, support, upgrades and finally retiring it.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx and OpEx","text":"CapEx is money spent up front on things you keep; OpEx is ongoing spending, like monthly bills.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Subscription","text":"Paying regularly, usually monthly or yearly, to keep using something.","also":["subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software you use online and pay for by subscription, while the maker runs it for you.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as you go","text":"Paying only for what you use, like cloud computing or AI tokens.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Overage","text":"Use above what your plan includes, which can cost extra.","also":["overages","overage charges"]},{"id":"billingalert","g":"money","word":"Billing alert","text":"A message when spending or use reaches a level you chose. It warns you, but doesn’t always stop further charges.","also":["billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Free tier","text":"A free level of a paid service, with limits. Handy for starting out.","also":["free plan"]},{"id":"pricing","g":"money","word":"Pricing plan","text":"The different packages a service sells, each with its own price and limits.","also":["pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licence","text":"The rules for how you may use, copy, change or share something someone else made, such as software, fonts or pictures.","also":["licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software whose code anyone can read, use and often change for free, under the rules of its licence.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Open source licence","text":"The rules that come with open source code. Some let you do almost anything (like MIT); some ask you to share your changes too (like GPL).","also":["open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietary","text":"Owned by a company and not free to copy or change. The opposite of open source.","also":["proprietary software"]},{"id":"copyright","g":"money","word":"Copyright","text":"The legal right of a creator to control copies of their work, including code and writing.","also":["copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Intellectual property (IP)","text":"Ideas and creations the law treats as owned, like code, designs, names and logos.","also":["intellectual property"]},{"id":"tos","g":"money","word":"Terms of service","text":"The rules you agree to when you use a service.","also":["terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contract","text":"A written agreement between two sides that the law will back up.","also":["contracts"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"A document setting out exactly what work will be done, by when and for how much.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Fixed price","text":"An agreed price for the whole job, however long it takes.","also":["fixed-price"]},{"id":"tm","g":"money","word":"Time and materials","text":"Paying for the hours really worked and the things really used, rather than a set price.","also":["T&M"]},{"id":"invoice","g":"money","word":"Invoice","text":"A bill asking for payment for work done or goods supplied.","also":["invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"When moving away from a supplier is so hard or costly that you are stuck with them.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Procurement","text":"The process of choosing and buying from suppliers."},{"id":"servicecredit","g":"money","word":"Service credit","text":"Money back or a discount you get when a supplier misses its SLA.","also":["service credits"]}]}};
